\subsection{Proof of [REF:thm:discrete]}
Here we use that $f(x)=f(x;\theta)=\inner{\theta,a(x)}_{\Hilbert'}$ for some feature map $a$ corresponding to the RKHS, which we only need for analytical purposes. Note such a decomposition exists for any RKHS: e.g. we can use a canonical feature map $a(x)=K(x,\cdot)$ corresponding to $\Hilbert'=\Hilbert.$ Similarly, we use $\theta_i:=P_i\theta$, where $P_i$ is the linear map that projects $\theta$ onto the span($\set{a(x)\mid x\in V_i}$). Next, denoting $H(\xt,\thetavec_i)$ as the Hessian of the discriminator
\begin{equation} 
    H(\x,\thetavec_i) := 
    \frac{\partial^2 f(\x,\thetavec_i)}{\partial \x^2}\in\Real^{d\times d},
\end{equation}
we first utilize a lemma from [CITE:becker2022instability].
\begin{lemma}[Lemma 4, Becker et al. 2022] 
Let  $\z^* = (\thetavec_i^*,\Xt^*_i)$ be an equilibrium
point and let $\Gamma(\z^*)$
be the spectrum of the Jacobian of the update map.
Then $\rho \in \Gamma(\z^*)$ if and only if
$\rho$ is of the form
\begin{equation} 
    \rho = 1 + \eta_d s,
\end{equation}
where $s$ is the root of the polynomial:
\begin{align}
    \MoveEqLeft \mathrm{det}(s\I - \A) 
    = (s+\lambda)^{p-Nd}
    \mathrm{det}\left((s+\lambda)(s\I_{Nd} + \Q) 
    + \R\right) 
\end{align}
and where $\Q$ and $\R$ are the block matrices 
with components
\begin{equation} 
    \Q_{ij} = -\mu \pt_i H(\xt_j^*,\theta^*)\delta_{ij}, 
    \quad
    \R_{ij} = \mu \pt_i \pt_j \frac{\partial^2}{\partial \x \partial \x'} \left. K(\x,\x') \right|_{\x=\xt_i^*,\x'=\xt_j^*}.
\end{equation}
\end{lemma}
When the kernel is an RBF, we can simplify expressions for $\Q$ and $\R$. First, we note that the value of the hessian of the optimal discriminator becomes:
\begin{align}
     H(\x_i, \theta_i^*) &= \left. \frac{\Delta_i}{\lambda}\frac{\partial^2}{\partial\x^2}K(\x,\x_i)\right|_{\x=\x_i}
    = \left. \frac{\Delta_i}{\lambda\sigma^2}\left(\frac{(\x-\x_i)(\x-\x_i)^\intercal}{\sigma^2}-\I_d\right)e^{\norm{\x-\x_i}/2\sigma^2}\right|_{\x=\x_i} =-\frac{\Delta_i}{\lambda\sigma^2}\I_d
\end{align}
Therefore, $\Q$ can now be written as:
$    Q = \frac{\mu\Delta_i}{\lambda\sigma^2}\text{diag}(\pt_1\I_d, \dots, \pt_N\I_d)
$
Next we have:
$
     \left. \frac{\partial^2}{\partial\x\partial\xt}K(\x,\x_i)\right|_{\x=\x'} 
    = \left. \frac{\Delta_i}{\lambda\sigma^2}\left(\frac{(\x-\x_i)(\x-\x_i)^\intercal}{\sigma^2}+\I_d\right)e^{\norm{\x-\x_i}/2\sigma^2}\right|_{\x=\x_i}
    =\frac{1}{\sigma^2}\I_d
$
Therefore the expression for $\R$ becomes:
\begin{equation}
    \R_{jk} = \frac{\mu\pt_j\pt_k}{\sigma^2}\I_d
\end{equation}
Single Point Case: In the simplest case we assume $N=1$. This means the $D(s)$ term can be written as a scalar times a diagonal matrix as follows:
\begin{align}
    D(s) &= \left((s+\lambda)(s+\frac{\mu\pt\Delta_i}{\lambda \sigma^2}) + \frac{\mu \pt^2}{\sigma^2}\right)\I_d 
    = \left(s^2 + (\lambda +\frac{\mu\pt\Delta_i}{\lambda \sigma^2})s + \frac{\mu\pt\Delta_i}{\sigma^2} + \frac{\mu \pt^2}{\sigma^2}\right)\I_d 
    = \left(s^2 + (\lambda +\frac{\mu\pt\Delta_i}{\lambda \sigma^2})s + \frac{\mu\pt p_i}{\sigma^2}\right)\I_d
\end{align}
Therefore $\mathrm{det}(D(s))$ becomes

$    \mathrm{det}(D(s)) =\left(s^2 + (\lambda +\frac{\mu\pt\Delta_i}{\lambda \sigma^2})s + \frac{\mu\pt p_i}{\sigma^2}\right)^d 
$

Solving for the roots of this polynomial we have:
\begin{align}
    s = -\frac{1}{2}(\lambda +\frac{\mu\pt\Delta_i}{\lambda \sigma^2}) \pm \frac{1}{2}\sqrt{(\lambda +\frac{\mu\pt\Delta_i}{\lambda \sigma^2})^2-4\frac{\mu\pt p_i}{\sigma^2}}
\end{align}
When $\Delta_i=0$, the eigenvalues simplify to
$
    s = \frac{1}{2}\left(-\lambda\pm \sqrt{\lambda^2-4\frac{\mu \pt^2}{\sigma^2}}\right).
$
Plugging $s$ back into the expression for $\rho$, we see that some of the jacobian eigenvalues must be:
$
    \rho = 1 - \frac{1}{2}\eta_d\lambda \left(1\pm\sqrt{1-4\frac{\mu\pt^2}{\lambda^2\sigma^2}}\right)
$

Multi-point Case: When $N>1$, we can write $D(s)$ as the following block matrix:
\begin{equation}
    D(s)_{jk} = \begin{cases} \left[(s+\lambda)(s+\frac{\mu \pt_j\Delta}{\lambda \sigma^2})+\frac{\mu \pt_j^2}{\sigma^2}\right] \I_d & j=k \\
    \left[\frac{\mu \pt_j\pt_k}{\sigma^2} \right]\I_d & j\neq k
    \end{cases}
\end{equation}
Note that because each block is diagonal and of the same dimension, their matrix products are commutative. Therefore, we can make use of the following theorem in [CITE:silvester2000determinants]:
\begin{theorem}[Theorem 1, Silvester 2000]
Let R be a commutative subring of ${}^nF^n$, where F is a field (or a commutative ring), and let$M\in{}^mR^m$. Then
\begin{equation}
    \mathrm{det}_F(M) = \mathrm{det}_F(\mathrm{det}_R(M))
\end{equation}
\end{theorem}
Let's assume that $\pt_j=\pt_k \: \forall j,k\in V_0$. This means that our block matrix is of the form:
$D(s) = \begin{bmatrix}
        D_1 & D_2 & \cdots & D_2 \\
        D_2 & D_1 & \cdots & D_2 \\
        D_2 & D_2 & \cdots & D_1 
        \end{bmatrix} = (D_1-D_2)(\I+\U\V^\intercal)$
Where $U^\intercal=(D_2,D_2 \dots)$, and $V^\intercal=((D_1-D_2)^{-1},(D_1-D_2)^{-1} \dots)$. Therefore by [REF:thm:det-det] and the matrix determinant lemma, we can write the determinant as:
\begin{align}
    \mathrm{det}(D(s)) &= \mathrm{det}\left((D_1-D_2)^N(\I_d + ND_1(D_2-D_1)^{-1}) \right) = \mathrm{det}\left(\left[(s+\lambda)(s+\frac{\mu\pt\Delta}{\lambda\sigma^2})\right]^N\left[1+N\frac{\mu\pt^2/\sigma^2}{(s+\lambda)(s+\frac{\mu\pt\Delta}{\lambda\sigma^2})}\right]\I_d\right) \nonumber \\
    &=\left[(s+\lambda)(s+\frac{\mu\pt\Delta}{\lambda\sigma^2})\right]^{Nd}\left[1+N\frac{\mu\pt^2/\sigma^2}{(s+\lambda)(s+\frac{\mu\pt\Delta}{\lambda\sigma^2})}\right]^d= \left[(s+\lambda)(s+\frac{\mu\pt\Delta}{\lambda\sigma^2})\right]^{(N-1)d}\left[(s+\lambda)(s+\frac{\mu\pt\Delta}{\lambda\sigma^2})+N\frac{\mu\pt^2}{\sigma^2}\right]^d\nonumber \\
    &= \left[(s+\lambda)(s+\frac{\mu\pt\Delta}{\lambda\sigma^2})\right]^{(N-1)d}\left[s^2 + (\lambda +\frac{\mu\pt\Delta_i}{\lambda \sigma^2})s + \frac{\mu\pt p_i}{\sigma^2}\right]^d = \left[(s+\lambda)(s+b)\right]^{(N-1)d}\left[s^2 + (\lambda +b)s + c\right]^d,
\end{align}
where, in the last step, we used the expressions for $b$
and $c$ in [REF:eq:abcdef].
The roots of the third polynomial are
$s = -\frac{\lambda + b}{2} \pm \sqrt{ \left(\frac{\lambda + b}{2}
    \right)^2 - c  }.$
Note that when $N=1$ this polynomial reduces to [REF:eq:simplest-eigen]. When $N>1$, the main difference is that we introduce a new root at $s=-\frac{\mu\pt\Delta}{\lambda\sigma^2}$. The full characteristic polynomial for matrix A can now be written as:
\begin{equation}
    \mathrm{det}(s\I-\A) = (s+\lambda)^{p-d}(s+\frac{\mu\pt\Delta}{\lambda\sigma^2})^{(N-1)d}\left[s^2 + (\lambda +\frac{\mu\pt\Delta_i}{\lambda \sigma^2})s + \frac{\mu\pt p_i}{\sigma^2}\right]^d
\end{equation}
The polynomial above has roots $a,b,$ or $c$, which proves the claim of Theorem [REF:thm:discrete].
\subsection{Proof of Corollary [REF:cor:etad-constraint] and Proposition [REF:prop:linear-sufficient-condition]}
From [REF:thm:discrete], we know that the eigenvalues of the linearized RBF Kernel GAN around the true point can be written as:
$\rho = \left\{1-\eta_d a,\: 1-\eta_d b,\: \left(1 -\eta_d\frac{(a+b)}{2}\right) \pm \eta_d\sqrt{\left[\frac{(a+b)}{2}\right]^2-c}\right\}
$.
Given that $|\rho|<1$ is a necessary condition for stability, we can derive some constraints on our hyperparameters. We assume here that $\lambda$, $\sigma$, and $\eta_d, \eta_g$ are all positive values.\\
Stability of $\rho_a$ and $\rho_b$: From the first two eigenvalues we have the condition:
$a \in (0,2/\eta_d), b \in (0,2/\eta_d)$
It is easy to see that we arrive at the conditions $\lambda < 2/\eta_d$ and $\Delta >0$. From the second bound we can substitute $\pt = (\Delta-\p_0)/N$ and solve a quadratic equation for bounds on $\Delta$:
\begin{align}
    \frac{\eta_g\pt\Delta}{\lambda \sigma^2} < 2 &\implies \eta_g(\frac{\Delta-\p_0}{N})\Delta <2\lambda\sigma^2 \implies \frac{\eta_g}{N} \Delta^2 + \frac{\eta_g\p_0}{N}\Delta-2\lambda\sigma^2 <0  
\end{align}
The roots of this quadratic are:
\begin{align}
    \Delta &= \frac{N}{2\eta_g}\left(-\frac{\eta_g\p_0}{N}\pm \sqrt{\frac{\eta_g^2\p_0^2}{N^2}+\frac{8\eta_g\lambda\sigma^2}{N}}\right) = -\frac{1}{2}\left(\p_0 \pm \p_0 \sqrt{1+\frac{8N\lambda\sigma^2}{\eta_g\p_0^2}}\right) =-\frac{\p_0}{2}\left(1 \pm \sqrt{1+\frac{8N\lambda\sigma^2}{\eta_g\p_0^2}}\right)
\end{align}
Therefore we have the additional bound on $\Delta$:
$\Delta \in \left[0, \frac{\p_0}{2}\left(-1 + \sqrt{1+\frac{8N\lambda\sigma^2}{\eta_g\p_0^2}}\right)\right]
$
The interval becomes $\Delta \in [0, \p_0]$ only if 
\begin{equation}
    \sqrt{1+\frac{8N\lambda\sigma^2}{\eta_g\p_0^2}} > 3 \\
    \implies \frac{N\lambda \sigma^2}{\eta_g} > \p_0^2
\end{equation}
It is sufficient to have $\lambda>\frac{\eta_g}{N\sigma^2}$ for this condition to hold. \\
Stability of $\rho_c$: Let us denote the quantity $\alpha:= \eta_d(a+b)/2=  (\eta_d\lambda +\frac{\eta_g\pt\Delta_i}{\lambda \sigma^2})/2$, and $\beta:=\eta_d^2c = \frac{\eta_d\eta_g\pt p_i}{\sigma^2}$. We know that when the previous conditions are satisfied $\alpha \in [0,2]$. We can write the third eigenvalue pair as:
\begin{equation}
    \rho = (1-\alpha)\pm\sqrt{\alpha^2-\beta}
\end{equation}
We know that $\beta > 0$ already because each component is positive. The last way these eigenvalues could have magnitude larger than 1 is if they have large imaginary components. The following constraint ensures these imaginary components are not too large:

\begin{align}
    (1-\alpha)^2 - \alpha^2 +\beta < 1 &\implies 1-2\alpha + \beta < 1 \implies \beta < 2\alpha \implies c < (a+b)/\eta_d
\end{align}
Using the inequalities $\pt p_0 <1$, $\Delta>0$, we get the last sufficient condition for our proposition:
\begin{equation}
    \lambda > \frac{\eta_g}{\sigma^2} \implies \frac{\eta_g\pt\p_0}{\sigma^2} < \lambda +  \frac{\mu\pt\Delta}{\lambda^2} \Leftrightarrow c < (a+b)/\eta_d
\end{equation}

