\SetAlgoLined
\KwIn{Functions $\mathcal{G}$, $\mathcal{D}$ and $\mathcal{E}$, Regularization parameters $\beta_n$, $\beta_c$, learning rate $\eta$,  parameters $\Theta_G^t$, $\Theta_E^t$ }
\KwOut{$\Theta_G^{(t+1)}, \Theta_E^{(t+1)}$}
Sample ${z^{(i)}}_{i=1}^m$ from $ \mathbb{P}^z , z = (z_n, z_c)$ \; 
$g_{\Theta_G} \gets \nabla_{\Theta_G} \left( -\sum\limits_{i=1}^m q(\mathcal{D}(\mathcal{G}(z^{(i)})) + \beta_n \sum\limits_{i=1}^m \| z_n^{(i)} - \mathcal{E}(\mathcal{G}(z_n^{(i)})) \|_2^2  + \beta_c \sum\limits_{i=1}^m \mathcal{H} (z_c^{(i)} ,\mathcal{E}(\mathcal{G}(z_c^{(i)}))) \right) $  \;
$g_{\Theta_E} \gets \nabla_{\Theta_E}  \left( \beta_n \sum\limits_{i=1}^m \| z_n^{(i)} - \mathcal{E}(\mathcal{G}(z_n^{(i)})) \|_2^2  +   \beta_c \sum\limits_{i=1}^m \mathcal{H} (z_c^{(i)} ,\mathcal{E}(\mathcal{G}(z_c^{(i)}))) \right) $ \;
Update $\Theta_G$ using $(g_{\Theta_G}, \Theta_G^t)$ with Adam ; similarly for $\Theta_E$. \;
\Return{$\Theta_G, \Theta_E$}\;
\caption{{\sc Update\_Param}}

\end{algorithm*}

