\begin{proof}[Proof of Theorem~[REF:thm:lower-bound]] \quad
The proof uses the standard Fano's inequality.
	\begin{lem}[Thm. 2.5 in [CITE:tsybakov2009introduction]]
		Assume that $H \geq 2$ and suppose $\Theta$ contains $\theta_0, \theta_1, \ldots, \theta_H$ such that:
		\begin{enumerate}
			\item $d(\theta_j, \theta_k) \geq 2s >0$, for all $j, k \in [H]$ and $j \neq k$.
			\item $\frac{1}{H} \sum_{j=1}^H D_{ KL}(P_{j}, P_0) \leq \alpha \log H$ with $0< \alpha < 1/8$ and $P_j = P_{\theta_j}$ for $j \in [H]$.
		\end{enumerate}
		Then for any estimator $\hat{\theta}$,
		\begin{align*}
			\sup_{\theta \in \Theta} P_\theta(d(\hat{\theta}, \theta) \geq s) \geq \frac{\sqrt{H}}{1+\sqrt{H}} \left( 1 - 2\alpha - \sqrt{\frac{2\alpha}{\log H}} \right) > 0.
		\end{align*}
	\end{lem}

	Let's construct a mixture of hypothesis on the function space $W^{\alpha, 2}(L)$, and a subset of discriminator functions in $W^{\beta, 2}(L)$, such that the multiple testing problem among the mixture of hypothesis is hard, and thus the loss induced by the best discriminator among the subset provides a lower bound on the estimation rate. Let's construct this mixture in the frequency domain. Choose $M>0$ to be determined later, denote the hypothesis class of interest to be
	\begin{align}
		\Omega_\alpha = \left\{ g_w(x) = \sum_{\xi \in [M]^d} c_{\alpha} w_\xi \psi_\xi(x), w \in \{0,1\}^{M^d} \right\},
	\end{align}
	where
	$$
	c_{\alpha} = \frac{L}{M^{d/2}(1+dM^2)^{\alpha/2}}.
	$$
	It is easy to verify that
	$\Omega_\alpha \subset W^{\alpha,2}(L)$
	because for any $g_w(x)$, we have
	\begin{align*}
		\sum_{\xi \in [M]^d} (1 + \| \xi\|_2^2 )^{\alpha} c_{\alpha}^2 \leq L^2.
	\end{align*}
	Similarly, let's consider $\Lambda_\beta \subset W^{\beta,2}(L)$
	\begin{align}
		\Lambda_\beta = \left\{ f_v(x) = \sum_{\xi \in [M]^d} c_{\beta} v_\xi \psi_\xi(x), v \in \{-1,1\}^{M^d} \right\},
	\end{align}
	where
	$$
	c_{\beta} = \frac{L}{M^{d/2}(1+dM^2)^{\beta/2}}.
	$$

	Take any $w, w'$, we know that
	\begin{align*}
		d(g_w, g_{w'}) &:= \sup_{f \in \F_D} \langle f, g_w \rangle_\pi - \langle f, g_{w'} \rangle_\pi \geq \sup_{f \in \Lambda_{\beta}} \langle f, g_w - g_{w'} \rangle \\
		& = \sup_{v} c_{\alpha} c_{\beta} \sum_{\xi\in [M]^d} v_{\xi} (w_{\xi} - w_{\xi}') \\
		& =  c_{\alpha} c_{\beta} \sum_{\xi \in [M]^d} I(w_\xi \neq w_{\xi}') =  c_{\alpha} c_{\beta} \rho(w, w'),
	\end{align*}
	where $\rho(w, w')$ denotes the Hamming distance between $w$ and $w'$ on the hypercube $\{0,1 \}^{M^d}$. Now we need to construct a subset over the hypercube such that for any pairs $w, w'$, they are separated in terms of Hamming distance.

	The Varshamov-Gilbert bound (Lemma 2.9 in [CITE:tsybakov2009introduction]) does the job. We know that there exist a subset $\{ w^{(0)}, \ldots, w^{(H)} \} \subset \{0,1\}^{h}$ such that $w^{(0)} = (0, \ldots, 0)$,
	\begin{align*}
		&\rho(w^{(j)}, w^{(k)}) \geq \frac{h}{8}, ~\forall~j, k\in [H],~ j\neq k, \\
		&\log H \geq \frac{h}{8} \log 2.
	\end{align*}
	In our case $h = M^d$.

	Now let's calculate the probability distance $P_j, P_0$ induced by hypothesis $w^{(j)}$ and $w^{(0)}$, for all $j \in [H]$ to show that information theoretically, it is hard to distinguish the mixture of hypothesis. The following holds,
	\begin{align*}
		D_{ KL}(P_j, P_0) &=  \frac{n}{2} c_\alpha^2 \sum_{\xi \in [M]^d} \left( w^{(j)}_{\xi} - w^{(0)}_{\xi} \right)^2 \\
		& \leq \frac{n}{2} c_\alpha^2 M^d.
	\end{align*}
	If we choose $M = \left( \frac{4L^2}{c \log 2} \frac{1}{d^\alpha} \right)^{\frac{1}{2\alpha+d}} \cdot n^{\frac{1}{2\alpha+d}} $, we know
	\begin{align*}
		\frac{1}{H} \sum_{j=1}^H D_{ KL}(P_j, P_0) \leq c \log H, ~\text{for some constant $c>0$.}
	\end{align*}
	In this case, for any $j \neq k \in [H]$
	\begin{align*}
		d(g_{w^{(j)}}, g_{w^{(k)}}) = c_\alpha c_\beta \rho(w^{(j)}, w^{(k)}) \geq \frac{M^d}{8} c_\alpha c_\beta = \frac{L^2}{(1+dM^2)^{\frac{\alpha+\beta}{2}}} \asymp  n^{-\frac{\alpha+\beta}{2\alpha +d}}.
	\end{align*}

	Therefore using Fano's Lemma, we reach
	{
	\begin{align*}
		\inf_{\hat{\nu}} \sup_{\nu \in \F_R} \E d_{\F_D}( \hat{\nu}, \nu) &= \inf_{\hat{g}} \sup_{g \in W^{\alpha,2}(L)} \E \sup_{f \in W^{\beta,2}(L)} \langle f, \hat{g} - g \rangle_\pi   \\
		&\geq \inf_{\hat{w}} \sup_{w \in \{w^{(0)},\ldots, w^{(H)}\}} \E d(g_{\hat{w}}, g_{w})\\
		&\geq \frac{L^2}{(1+dM^2)^{\frac{\alpha+\beta}{2}}} \cdot \inf_{\hat{w}} \sup_{w \in \{w^{(0)},\ldots, w^{(H)}\}} P\left(d(g_{\hat{w}}, g_{w}) \geq \frac{L^2}{(1+dM^2)^{\frac{\alpha+\beta}{2}}} \right) \succsim n^{-\frac{\alpha+\beta}{2\alpha +d}}.
	\end{align*}}

\end{proof}

\begin{proof}[Proof of Theorem~[REF:thm:deep-relu-learn]] \quad
	We outline the key steps of the proof. Due to the approximation property of the network class $\F_D$ to $W^{\beta, \infty}(1)$, and $\mu_G$ to $W^{\alpha, \infty}(1)$, we know that
	\begin{align*}
		\max_{f \in W^{\beta, \infty}(1)} \min_{f' \in \F_D} \| f - f' \|_\infty \leq \epsilon, \\
		\min_{\mu \in \mu_G} d_{\F_D}(\mu, \nu) = \sup_{f \in \F_D} \| f\|_{1} \| \mu - \nu \|_{\infty} \leq M \epsilon
	\end{align*}
	because $F_D \subseteq W^{0, \infty}(M)$.
	Apply the oracle inequality [REF:eq:oracle-2], one has
	\begin{align*}
		d_{W^{\beta, \infty}(1)}(\tilde{\mu}_n, \nu) &\leq \min_{\mu \in \mu_G} d_{\F_D}(\mu, \nu) + (1+ \| \tilde{\nu}_n \|_1) \cdot \max_{f \in W^{\beta, \infty}(1)} \min_{f' \in \F_D} \| f - f' \|_{\infty} \\
		& \quad \quad + d_{\F_D}(\nu, \hat{\nu}_n) + d_{W^{\beta, \infty}(1)}(\tilde{\nu}_n, \nu), \\
		d_{W^{\beta, \infty}(1)}(\tilde{\mu}_n, \nu) - d_{\F_D}(\nu, \tilde{\nu}_n) & \leq (M+2)\epsilon + d_{W^{\beta, \infty}(1)}(\tilde{\nu}_n, \nu).
	\end{align*}
	Here the last step we use the following fact
	\begin{align*}
		\| \tilde{\nu}_n\|_1 \leq  \| \tilde{\nu}_n - \nu \|_1 + 1 \leq \| \tilde{\nu}_n - \nu \|_2  + 1   \leq 1 + L\sqrt{C} n^{-\frac{\alpha}{2(\alpha+\beta)+d}} \leq 2.
	\end{align*}

	It is clear that for $k \in \mathbb{N}$, $W^{k, \infty}(1)$ is a subspace of $W^{k, 2}(r_k)$ under some scaling $r_k$, in the following sense that
	\begin{align*}
		r_k := \sqrt{1+k d^k}, ~~W^{k, \infty}(1) \subset W^{k, 2}(r_k).
	\end{align*}
	Therefore for any $\nu \in W^{\alpha, \infty}(1)$,
	\begin{align*}
		& \E d_{W^{\beta, \infty}(1)}(\tilde{\nu}_n, \nu) \leq \E d_{W^{\beta, 2}(r_\beta)}(\tilde{\nu}_n, \nu) \\
		&\leq \sup_{\nu \in W^{\alpha, 2}(r_\alpha)} \E d_{W^{\beta, 2}(r_\beta)}(\tilde{\nu}_n, \nu) \precsim \min\left\{ n^{ - \frac{\alpha+\beta}{2(\alpha+\beta)+d}}, n^{-\frac{\beta}{d}} + n^{-\frac{1}{2}}  \right\} =: n^{-c(\alpha, \beta, d)}
	\end{align*}
	where the last line follows from Theorem~[REF:thm:non-param]. Combine with the approximation error, we reach
	\begin{align*}
		\E d_{W^{\beta, \infty}(1)}(\tilde{\mu}_n, \nu)- \E d_{\F_D}(\tilde{\nu}_n, \nu) \leq (M+2)\epsilon + C n^{-c(\alpha, \beta, d)}.
	\end{align*}
	Under the assumption that $\F_D \subseteq W^{\beta, 2}(L)$, then
	\begin{align*}
		\E d_{\F_D}(\tilde{\nu}_n, \nu) \leq \E d_{W^{\beta, 2}(L)}(\tilde{\nu}_n, \nu) \precsim n^{-c(\alpha, \beta, d)}.
	\end{align*}
	Putting things together, we have proved $\E d_{W^{\beta, \infty}(1)}(\tilde{\mu}_n, \nu) \leq C_1 \epsilon + C_2 n^{-c(\alpha, \beta, d)}.$

	For the lower bound, the construction of the mixture is slightly different to the construction in Theorem~[REF:thm:lower-bound] (this time the construction is in the spacial domain, and for the density estimation problem). Another difference here lies we need to construct hypothesis in $W^{\alpha, \infty}(1)$ (also called the H\"{o}lder space) instead of $W^{\alpha, 2}(L)$. Our construction is motivated from [CITE:tsybakov2009introduction] Page 103 and Theorem 2.8, but note the difference here is that we need to make sure each hypothesis is indeed a valid density function in $W^{\alpha, \infty}(1)$ in $\mathbb{R}^d$.
	Choose a kernel function $K(x) = a \exp(-\frac{1}{1 - 4x^2}) I(|x|<1/2)$ for some small $a>0$ to ensure that $K(x) \in W^{\alpha \vee \beta, \infty}(1)$. Let $m$ be a parameter to be determined later, and denote $h_n = 1/m$.

	Define the hypothesis class to be
	\begin{align*}
		\Omega_\alpha = \left\{ g_w(x) = \frac{1}{1+c_w}\left( 1 + \sum_{\xi \in [m]^d} w_\xi h_n^{\alpha} \varphi_\xi(x) \right), w \in \{0,1\}^{m^d} \right\} , \\
		\Lambda_\beta = \left\{ f_v(x) = \sum_{\xi \in [m]^d} v_\xi h_n^{\beta} \varphi_\xi(x), v \in \{-1,1\}^{m^d} \right\},
	\end{align*}
	where
	\begin{align*}
 	   \varphi_\xi(x) &=  \prod_{i=1}^d K\left(\frac{x_i - \frac{\xi_i - 1/2}{m}}{h_n} \right), ~~\text{$h_n = 1/m$},\\
	   c_w &= \int \sum_{\xi \in [m]^d} w_\xi h_n^{\alpha} \varphi_\xi(x)  dx.
	\end{align*}
	Let's bound $c_w$, for any $w$
	\begin{align*}
		0\leq c_w = \sum_{\xi \in [m]^d} \int  w_\xi h_n^{\alpha} \varphi_\xi(x)  dx \leq \sum_{\xi \in [m]^d} \int  h_n^{\alpha + d} \prod_{i=1}^d K\left(u_i \right) du \leq m^d h_n^{\alpha + d} a^d \leq a^d h_n^{\alpha} \ll 1/100,
	\end{align*}
	and $\| (g_w(x) - g_{0}(x))/g_w(x)\|_{\infty} \leq c_w + a^d h_n^{\alpha} \ll 1/50$.
	It is easy to verify (1) $\Omega_\alpha \subset W^{\alpha, \infty}(L)$ for some $L$, and each element in the set is a valid density; (2) $\Lambda_\beta \subset W^{\beta, \infty}(1)$, as for any multi-index $\gamma$,
	\begin{align*}
		\| D^{(\gamma)} g_w(x) \|_{\infty} \precsim h_n^{\alpha - |\gamma|}, ~~ \| D^{(\gamma)} f_v(x) \|_{\infty} \precsim h_n^{\beta - |\gamma|}.
	\end{align*}

	To apply the Fano's Lemma, let's first show that the hypothesis are separated in the evaluation metric. Let's use the same subset $\{ w^{(0)}, \ldots, w^{(H)} \} \subset \{0,1\}^{h}$ claimed by the Varshamov-Gilbert bound
	\begin{align*}
		&\rho(w^{(j)}, w^{(k)}) \geq \frac{h}{8}, ~\forall~j, k\in [H],~ j\neq k, \\
		&\log H \geq \frac{h}{8} \log 2.
	\end{align*}
