		D_{ KL}(P_{w^{(j)}}^{\otimes n}, P_{w^{(0)}}^{\otimes n}) & = n D_{ KL}(P_{w^{(j)}}, P_{w^{(0)}}) \\
		& = n \int  - \log \left( 1 + \frac{g_{0} - g_{w^{(j)}}}{g_{w^{(j)}}} \right) g_{w^{(j)}} dx \\
		& \leq n \int \frac{[g_{0} - g_{w^{(j)}}]^2}{g_{w^{(j)}}} dx \leq 1.01 n \sum_{\xi \in [m]^d} \int  h_n^{2\alpha} \varphi_\xi^2(x)  dx \\
		& \leq 1.01 n \sum_{\xi \in [m]^d} \int  h_n^{2\alpha+d} \prod_{i=1}^d K^2\left(u_i \right) du
		 \precsim n h_n^{2\alpha +d} m^d.
	\end{align*}
	Therefore if we choose $m \asymp n^{-\frac{1}{2\alpha + d}}$, we know
	$\frac{1}{H} \sum_{j=1}^H D_{ KL}(P_{w^{(j)}}^{\otimes n}, P_{w^{(0)}}^{\otimes n}) \leq c \log H = c' m^d$.
	Using the Fano's Lemma, the lower bound for density estimation is of the order $h_n^{\alpha+\beta} = n^{-\frac{\alpha+\beta}{2\alpha+d}}$, as
	\begin{align*}
		\inf_{\nu_n} \sup_{d\nu/dx \in W^{\alpha, \infty}(L)}\E d_{W^{\beta, \infty}(1)}(\nu_n, \nu) &= \inf_{\hat{g}} \sup_{g \in W^{\alpha,\infty}(L)} \E \sup_{f \in W^{\beta,\infty}(1)} \langle f, \hat{g} - g \rangle   \\
		&\geq \inf_{\hat{w}} \sup_{w \in \{w^{(0)},\ldots, w^{(H)}\}} \E d(g_{\hat{w}}, g_{w})\\
		&\geq C_3 \left( n^{-\frac{\alpha+\beta}{2\alpha + d}} + n^{-\frac{1}{2}}\right).
	\end{align*}
\end{proof}

\begin{proof}[Proof of Theorem~[REF:thm:relu-discrimin]] \quad
Claim that for any $f(x) \in \F^{(\ell)}(V)$, $f$ is $V^{\ell}$-Lipschitz with respect to the $\ell_\infty$-metric.
		Prove through induction. When $\ell = 1$, $| f(x) - f(y) | = |\sum_j w_j (x_j - y_j)| \leq \| w\|_1 \|x - y \|_{\infty} \leq V\|x - y \|_{\infty}$. Assume for general $\ell$, the claim is true, let's prove for $f \in \F^{(\ell+1)}(V)$
		\begin{align*}
			|f(x) - f(y)| &=  \left| \sum_j w_j \left[ \sigma (f_j(x)) - \sigma(f_j(y)) \right] \right| \\
			&\leq \| w\|_1 \max_j \| \sigma (f_j(x)) - \sigma(f_j(y))  \| \\
			& \leq V \max_j | f_j(x) - f_j(y) | \leq V \cdot V^{\ell} \| x- y \|_{\infty} = V^{\ell+1} \| x- y \|_{\infty}.
		\end{align*}

	Observe that
		$\forall f \in \F^{\ell}(V)$, the following inequality holds
		\begin{align*}
			\max_{|\alpha| \leq 1}\| D^{\alpha} f \|_{\infty} \leq V^{\ell}, \\
			\left( \sum_{|\alpha| \leq 1} \| D^{\alpha} f \|_2^2 \right)^{1/2} \leq (d+1)^{\frac{1}{2}} V^{\ell}.
		\end{align*}
		In other words, $f \in \F_D \subset W^{1, 2}\left( \sqrt{d+1} V^{\ell}  \right)$.

