	\begin{align*}
		\E d_{\F_D}(\tilde{\mu}_n, \nu) -  \min_{\mu \in \mu_G} d_{\F_D}(\mu, \nu) \leq 2 \E d_{\F_D} (\nu, \tilde{\nu}_n) \leq 2 \E d_{W^{1, 2}\left( \sqrt{d+1} V^{\ell}  \right)} (\nu, \tilde{\nu}_n).
	\end{align*}
	Apply Theorem~[REF:thm:non-param] (Eqn.~[REF:eq:l_a_l_b]) with $\beta = 1$, $L_\alpha = L$, $L_\beta = \sqrt{d+1} V^{\ell}$, we can complete the proof.
\end{proof}

\begin{lem}[Relative Ordering]

	Consider the following two function spaces on $\mathbb{R}^d$
	\begin{align*}
		\F_{ Lip,\ell_\infty}(L, M) := \{ f: |f(x) - f(y)| \leq L \|x - y \|_{\infty},~\forall x, y, ~\text{and}~ \| f\|_{\infty} \leq M \},\\
		\F_{ Lip, \ell_2}(L, M) : = \{ f: |f(x) - f(y)| \leq L \|x - y \|_{2},~ \forall x, y,~\text{and}~ \| f\|_{\infty} \leq M  \}.
	\end{align*}
	The following holds true
	\begin{align*}
		\F_{ Lip,\ell_\infty}(L, M) \subseteq  \F_{ Lip,\ell_2}(L, M) \subseteq W^{1, \infty}(L \vee M),\\
		\F_{ Lip,\ell_\infty}(dL, L) \supseteq  \F_{ Lip,\ell_2}(\sqrt{d}L, L) \supseteq W^{1, \infty}(L).
	\end{align*}
\end{lem}
\begin{proof} \quad
	Without loss of generality assume the function is differentiable. Then
	$$W^{1, \infty}(L) = \{f: |f(x) - f(y)| \leq L \|x - y \|_{1},~\forall x, y, ~\text{and}~ \| f\|_{\infty} \leq L \}.$$
	Observe that $\|x - y \|_1 \geq \| x- y \|_{2} \geq \| x- y \|_{\infty}$. Then $|f(x) - f(y)| \leq L \|x - y \|_{\infty} \leq L \|x - y \|_{2} \leq L \| x - y\|_1$.
	For the other side of the inequality, $\|x - y \|_1 \leq \sqrt{d} \| x- y \|_{2} \leq d \| x- y \|_{\infty}$, hence
	$|f(x) - f(y)| \leq L \|x - y \|_{1} \leq L\sqrt{d} \|x - y \|_{2} \leq Ld \| x - y\|_\infty$.
\end{proof}

