\begin{proof}[Proof of Theorem~[REF:thm:optimal-rates-rkhs]]
	The proof logic of this corollary follows similarly as in Theorem~[REF:thm:optimal-rates-sobolev]. We need to adapt the proof to the density ratio w.r.t. the general base measure $\pi$. Express $f \in \F$ under the eigenfunctions
	\begin{align*}
		f(x) = \sum_{i \in \mathbb{N}} f_i \psi_i(x), ~\text{with}~ \sum_i t_i^{-1} f_i^2 \leq 1
	\end{align*}
	where $t_i \asymp i^{-\kappa}$ and $f_i = \int f\psi_i  d\pi$ are the coefficients. Consider the series representation of the target density $d \nu /d\pi$ w.r.t. the base measure $\pi$
	\begin{align*}
		\frac{d\nu}{d\pi}(x) =  \sum_{i \in \mathbb{N}} \nu_i \psi_i(x), ~\text{then}\\
		\| \cT_{\pi}^{-(\lambda-1)/2} \frac{d \nu}{d\pi} \|_{\cH} \leq r ~\text{is equivalent to}~ \sum_i t_i^{-\lambda} \nu_i^2 \leq r^2 .
	\end{align*}
	Define the regularized density
	\begin{align*}
		\frac{d \widetilde{\nu}_n}{d\pi}(x):= \sum_{i \in \mathbb{N}}  \widetilde{\nu}_i \psi_{i}(x),
	\end{align*}
	where based on i.i.d. samples $X^{(1)}, X^{(2)}, \ldots X^{(n)} \sim \nu$
	\begin{equation*}
		\widetilde{\nu}_i :=
		\begin{cases}
		\frac{1}{n} \sum_{j=1}^n \psi_{i}(X^{(j)}), & \text{for}~ i \leq M \\
		0, &\text{otherwise}
		\end{cases}.
	\end{equation*}
	Follow the sample logic as in the proof of Theorem~[REF:thm:optimal-rates-sobolev], we have for any $\nu(x) \in \G$, with the optimal choice of an integer $M \asymp n^{\frac{1}{\lambda \kappa+1}}$, the following holds
	\begin{align*}
		\E d_{\F}(\nu, \widetilde{\nu}_n) & = \E \int f (d\nu - d\widetilde{\nu}_n) \\
		&= \E \int f \left( \frac{d\nu}{d\pi} - \frac{d \widetilde{\nu}_n}{d\pi} \right) d\pi \\
		&\leq \E \sup_{f \in \F}  \sum_{i\leq M} f_i \left(   \nu_i - \widetilde{\nu}_i \right) +  \E \sup_{f \in \F} \sum_{i > M} f_i  \nu_i.\\
		& \leq  \sqrt{\sum_{i\leq M} t_i^{-1} f_i^2 } \sqrt{\sum_{i\leq M} t_i \E (\widetilde{\nu}_i - \nu_i)^2 } +  Cr t_M^{\frac{\lambda+1}{2}} \\
		& \asymp \inf_{M \in \mathbb{N}} \left\{  \sqrt{C \frac{M^{1-\kappa} \vee 1}{n} } +  C r \sqrt{\frac{1}{M^{\kappa(\lambda+1)}}} \right\} \\
		&\precsim n^{-\frac{(\lambda+1)\kappa}{2\lambda \kappa+2}} \vee n^{-\frac{1}{2}}.  \nonumber
	\end{align*}

\end{proof}

\begin{proof}[Proof of Theorem~[REF:thm:nonparam-gans]]
	Consider first the Wasserstein GAN case.
	By the entropy integral Lemma~[REF:lem:symmetrization], 
	 if $\F_D$ consists of $L$-Lipschitz functions (Wasserstein GAN) on $\mathbb{R}^d$, $d\geq 2$, plug in the $\ell_\infty$-covering number bound for Lipschitz functions,
		\begin{align*}
			&\log \mathcal{N}(\epsilon, \F_{D}, \| \cdot \|_{\infty}) \leq C \left( \frac{L}{\epsilon} \right)^d, \\
			&\E d_{\F_D}(\nu, \widehat{\nu}^{n}) \leq 2 \inf_{0<\delta<1/2} \left( 4\delta + \frac{8 \sqrt{2}}{\sqrt{n}} \int_{\delta}^{1/2}  \sqrt{\log \mathcal{N}(\epsilon, \F_{D}, \| \cdot \|_{\infty}) } d \epsilon \right) \\
			&  \quad \quad \leq 16 \left( \frac{4\sqrt{2C}}{d-2}\right)^{\frac{2}{d}} L n^{-\frac{1}{d}} = \mathcal{O}\left( \left(\frac{C}{d^2 n} \right)^{-\frac{1}{d}} \right).
		\end{align*}
		This matches the best known bound as in [CITE:canas2012learning] (Section 2.1.1).

	Let's consider now the Sobolev GAN when $\F_D$ denotes Sobolev class $W^{\beta, 2}$ on $\mathbb{R}^d$. Recall the entropy number estimate for $W^{\beta, 2}$ [CITE:nickl2007bracketing], we have
		\begin{align*}
			&\log \mathcal{N}(\epsilon, \F_{D}, \| \cdot \|_{\infty}) \leq C \left( \frac{1}{\epsilon} \right)^{\frac{d}{\beta} \vee 2},\\
			&\E d_{\F_D}(\nu, \widehat{\nu}^{n}) \leq \mathcal{O}\left( n^{-\frac{\beta}{d}} + \frac{\log n}{\sqrt{n}} \right).
		\end{align*}






		For the regularized distribution as plug-in, one can apply Lemma~[REF:lem:oracle-ineq] and Theorem~[REF:thm:optimal-rates-sobolev] to obtain the claimed result.
\end{proof}

\begin{proof}[Proof of Corollary~[REF:coro:GMM]]
	First, let us show why GMM is a special case of the adversarial framework. Denote a vectored-value function $\Phi(\cdot): \Omega  \rightarrow \mathbb{R}^{K}$ with elements $\Phi(x)[k] = \phi_k(x)$. [REF:eq:gan-nonparam] is equivalent to 
	\begin{align}
		\min_{\mu \in \D_G} \big(\E_{Y\sim \mu} \Phi(Y) - \E_{X\sim \widehat\nu^n} \Phi(Y) \big)^\top \bW \big(\E_{Y\sim \mu} \Phi(Y) - \E_{X\sim \widehat\nu^n} \Phi(Y) \big)
	\end{align}
	which is precisely moment-matching between $\mu$ and $\widehat\nu^n$ with weight matrix $\bW$. By Lemma~[REF:lem:oracle-ineq], we need to bound $\E d_{\F_D}(\nu, \widehat\nu^n)$ now. Using the symmetrization Lemma~[REF:lem:symmetrization], $\E d_{\F_D}(\nu, \widehat\nu^n) \leq 2\E \cR_n \left(\F_D\right)$. Let's calculate the Rademacher complexity 
	\begin{align*}
		\E \cR_n \left(\F_D\right) &= \frac{1}{n} \E_{X_1,\ldots, X_n\sim \nu} \E_{\epsilon} \sup_{\omega: \omega^\top \bW^{-1} \omega \leq 1}\sum_{l \in [n]} \epsilon_l  \sum_{i \in [K]} \omega_i \phi_{i}(X_l) \\
		&= \frac{1}{n} \E_{X_1,\ldots, X_n\sim \nu} \sqrt{ \sum_{i,j\in [K]} [\sum_{l\in [n]} \epsilon_l \phi_i(X_l)]\bW_{ij}[\sum_{l\in [n]} \epsilon_l \phi_j(X_l)] } \\
		& \leq \frac{1}{n} \E_{X_1,\ldots, X_n\sim \nu}\sqrt{ \E_{\epsilon}  \sum_{i,j\in [K]} [\sum_{l\in [n]} \epsilon_l \phi_i(X_l)]\bW_{ij}[\sum_{l\in [n]} \epsilon_l \phi_j(X_l)] } \\
		& = \frac{1}{n} \E_{X_1,\ldots, X_n\sim \nu}\sqrt{ \sum_{i,j\in [K]} \sum_{l\in [n]} \phi_i(X_l)\bW_{ij} \phi_j(X_l) } \\
		& \leq \sqrt{\frac{\E_{X\sim \nu}[\sum_{i,j\in [K]} \bW_{ij} \phi_i(X) \phi_j(X) ]}{n}}
	\end{align*}
	where the third and the fourth steps uses the Jensen's inequality.
\end{proof}

\begin{proof}[Proof of Corollary~[REF:cor:wass]]

	Now let's consider Wasserstein distance. Consider in addition the Lipschitz constants of $\F$ to be $L_{\F}$, and $\G$ to be $L_{\G}$, namely
	\begin{align*}
		| f_{\omega}(x) - f_{\omega}(x') | \leq L_{\F} \| x - x' \| \\
		\| g_{\theta} (z) -  g_{\theta} (z') \| \leq L_{\G} \| z - z' \|
	\end{align*}

	Consider first the case when $Z\sim N(0, I_d)$ (unbounded). Then for any $f \in Lip(1)$, we know
	\begin{align}
		f(g_\theta(z)) \in Lip(L_{\G}).
	\end{align}
	In other words, $f \circ g_{\theta} (Z)$ are $L_{\G}^2$ sub-Gaussian (Lemma~[REF:lem:pinsker-bobkov]), 
	therefore
	\begin{align*}
		d_{W}^2 \left( \nu, \mu_{\widehat{\theta}} \right) \leq 2 L_{\G}^2 \cdot  d_{KL} \left( \nu || \mu_{\widehat{\theta}} \right) 
	\end{align*}
	and
	\begin{align*}
		d_{\F} \left( \nu, \mu_{\theta} \right) &\leq L_{\F}  \cdot d_{W}\left( \nu, \mu_{\theta} \right) \\
		& \leq \sqrt{2} L_{\F} L_{\G} \sqrt{ d_{KL} \left( \nu || \mu_{\theta} \right)  }.
	\end{align*}
	Follow the analysis with as in the TV distance, we have
	\begin{align*}
		\E d_W^2 \left( \nu, \mu_{\widehat{\theta}} \right) & \leq  L_{\G}^2 \sup_{\theta} \inf_{\omega} \left\| \log \frac{p_\nu}{p_{\mu_{\theta}}} - f_\omega \right\|_{\infty} +   L_{\G}^3 L_{\F} \inf_\theta  \left\| \log \frac{p_{\mu_\theta}}{p_\nu} \right\|_{\infty}^{1/2} \\
		& \quad \quad + C \sqrt{\text{Pdim}(\F) \left( \frac{\log m}{m} \vee \frac{\log n}{n} \right)} + C \sqrt{  \text{Pdim}(\F \circ \G) \frac{\log m}{m} }.
	\end{align*}

	Consider then the case when $z,x \in [0, 1]^d$ in bounded region, we know
	\begin{align}
		\| g_{\theta} (z) -  g_{\theta} (z') \| \leq L_{\G} \sqrt{d}
	\end{align}
	Therefore $\| g_{\theta}(z) \| \leq M + L_{\G} \sqrt{d}$, and the support of $g_{\theta}(Z)$ lies in an $\ell_2$ ball with $R:= M + (L_{\G}+1) \sqrt{d}$.
	Hence
	\begin{align*}
		\E d_W^2 \left( \nu, \mu_{\widehat{\theta}} \right) & \leq R^2 \E d_{TV}^2 \left( \nu, \mu_{\widehat{\theta}} \right).
	\end{align*}
	The reason is: for any $f(x)$ that has Lipchitz constant $1$ with $f(0) = 0$, it is true that
	$f(x)$ is bounded in a bounded domain with radius $R$. Such a centering of $f$ is without loss of generality since $\sup_{f: f \in Lip(1)} \int f(\mu - \nu) dx = \sup_{f-f(0): f \in Lip(1)} \int (f-f(0))(\mu - \nu) dx $, for probability distributions $\mu, \nu$.

\end{proof}

\begin{proof}[Proof of Corollary~[REF:cor:multivariate-gaussian]]
	Suppose $\log p_\nu(x) = -\frac{1}{2}(x - b_*)' \Sigma_*^{-1} (x- b_*) + \frac{1}{2}\log \det (\Sigma_*^{-1}) - \frac{d}{2} \log (2\pi).$ And the generator class is depth-one NN, with weights $\theta = (W, b)$, $X = W Z + b$, then
	$\log p_{\mu_\theta}(x) = -\frac{1}{2} (x - b)' (W W')^{-1} (x - b) + \frac{1}{2} \log \det ((W W')^{-1}) - \frac{d}{2} \log (2\pi)$.

	For the discriminator, with the activation function $\sigma(t) = t^2$, one can use $O(d)$ units in a discriminator network with depth $2$, so that the two approximation error terms are zero. Note that one can also realize the quadratic activation with the ReLU activation in a bounded domain, using the construction in [CITE:yarotsky2016error]. By Lemma~[REF:lem:VC-dim-bound] with degree at most $2$, $\text{VCdim}(\F) \precsim d^2 \log d$, $\text{VCdim}(\F \circ \G) \precsim (pd+d^2) \log (p + d)$. 
	Therefore $$\E d^2_{TV}\left( g_{\theta}(Z), X  \right)  \leq C \left(\frac{d^2 \log d}{n \wedge m} + \frac{(pd+d^2) \log (p + d)}{m}\right)^{1/2}.$$
\end{proof}

\subsection{Supporting Lemmas}

Let's define the empirical Rademacher complexity,
\begin{align}
	\cR_n \left(\F\right) := \E_{\epsilon} \sup_{f \in \F} \frac{1}{n} \sum_{i=1}^n \epsilon_i f(X_i),
\end{align}
where $\epsilon = (\epsilon_1,\ldots,\epsilon_n)$ are i.i.d. Rademacher random variables.

\begin{lemma}[Symmetrization and entropy integral]

		For $\widehat{\nu}^n = \frac{1}{n}\sum_{i=1}^n \delta_{X_i}$,
		\begin{align}
			\E d_{\F}(\nu, \widehat{\nu}^n) \leq 2 \E \cR_n \left(\F\right).
		\end{align}
		Assume $\sup_{f \in \F} \| f \|_{\infty} \leq 1$, one has the standard entropy integral bound,
		\begin{align*}
			\E d_{\F}(\nu, \widehat{\nu}^n) \leq  2 \E \inf_{0<\delta<1/2} \left( 4\delta + \frac{8 \sqrt{2}}{\sqrt{n}} \int_{\delta}^{1/2}  \sqrt{\log \mathcal{N}(\epsilon, \F, \| \cdot \|_{n}) } d \epsilon \right),
		\end{align*}
		where $\| f \|_n:= \sqrt{1/n \sum_{i=1}^n f(X_i)^2}$ is the empirical $\ell_2$-metric on data $\{X_i\}_{i=1}^n$, and $\mathcal{N}(\epsilon, \F, \| \cdot \|_{n})$ is the $\ell_2$-covering number.
\end{lemma}
Remark that since $\| f \|_n \leq \max_i |f(X_i)|$, and thus $\mathcal{N}(\epsilon, \F, \| \cdot\|_n) \leq \mathcal{N}(\epsilon, \F|_{X_1 \ldots, X_n}, \infty)$. Therefore, the upper bound in the above Lemma also holds with $\mathcal{N}(\epsilon, \F|_{X_1 \ldots, X_n}, \infty)$, the $\ell_\infty$-covering number on the data.

\begin{proof}
	We use the Dudley entropy integral, a standard result in empirical process theory. For the first inequality, apply the standard symmetrization technique, we have
	\begin{align*}
		\E d_{\F}(\nu, \widehat{\nu}^n) \leq \E_{X, X'} \sup_{f \in \F} \frac{1}{n} \sum_{i=1}^n f(X_i) - f(X_i') \leq 2 \E_{X} \E_{\epsilon} \sup_{f \in \F} \frac{1}{n} \sum_{i=1}^n \epsilon_i f(X_i).
	\end{align*}
\end{proof}

The next two results, Theorems 12.2 and 14.1 in [CITE:anthony2009neural], show that the metric entropy may be bounded in terms of the pseudo-dimension.
\begin{lemma}

	Assume for all $f \in \F$,  $\| f \|_{\infty} \leq M$. Denote the pseudo-dimension of $\F$ as ${ Pdim}(\F)$, then for $n \geq { Pdim}(\F)$, we have for any $\epsilon$ and any $X_1, \ldots, X_n$,
	\[
		 \mathcal{N}(\epsilon, \F|_{X_1, \ldots, X_n}, \infty) \leq \left( \frac{2e M \cdot n}{\epsilon \cdot { Pdim}(\F)} \right)^{{ Pdim}(\F)}.
	\]
\end{lemma}

\begin{lemma}
	If $\F$ is the class of functions generated by a neural network with a fixed architecture and fixed activation functions, then
	\[
		{ Pdim}(\F) \leq  { VCdim}(\tilde{\F})
	\]
	where $\tilde{\F}$ has only one extra input unit and one extra computation unit compared to $\F$. 
\end{lemma}

\begin{lemma}[Rademacher complexity and Pseudo-dimension]

	Under the condition $\max_i |f(X_i)| \leq B$, then for any $n \geq { Pdim}(\F)$,
	\begin{align*}
		\cR_n(\F) \leq C \cdot B \sqrt{ \frac{{ Pdim}(\F) \log n}{n} }
	\end{align*}
	for some universal constant $C>0$. 
\end{lemma}
\begin{proof}
	The proof is a direct application of the Dudley entropy integral in Lemma~[REF:lem:symmetrization] and the covering number bound by pseudo-dimension in Lemma~[REF:lem:ps-dim]. See A.2.2 in \cite*{farrell2018DeepNeural} for details. 
\end{proof}

\begin{lemma}[Theorem 6 in [CITE:Bartlett-etal2017_COLT], Vapnik-Chervonenkis dimension]

		Consider function class computed by a feed-forward neural network architecture with $W$ parameters and $U$ computation units arranged in $L$ layer. Suppose that all non-output units have piecewise-polynomial activation functions with $p+1$ pieces and degree no more than $d$, and the output unit has the identity function as its activation function. Then the VC-dimension and pseudo-dimension is upper bounded
		\[
			{ VCdim}(\F), { Pdim}(\F) \leq C \cdot \left( LW \log (pU) + L^2 W \log d\right),
		\]
		with some universal constants $C>0$. The same result holds for pseudo-dimension ${ Pdim}(\F)$.	
\end{lemma}

\begin{lemma}[[CITE:van2014probability], special case of Theorem 4.8 and Example 4.9]

	For any two random variables $g_{\theta}(Z), X \in \mathbb{R}^d$ with $g_{\theta}(Z) \sim \mu_\theta$ and $X \sim \nu$, Pinsker's inequality asserts that
	\begin{align*}
		2 d_{TV}^2\left( \mu_\theta, \nu  \right) \leq  d_{KL} \left(  \mu_\theta || \nu  \right).
	\end{align*}

	Assume in addition that $Z \sim N(0, I_d)$ to be isotropic Gaussian and for all $\theta$, $\|g_\theta(z) - g_\theta(z')\| \leq L \| z - z' \|$ is $L$-Lipschitz. Then for any $X \sim \nu$ and $g_{\theta}(Z) \sim \mu_\theta$
	\begin{align*}
		d_{W}^2\left(  \nu, \mu_{\theta}  \right) \leq  2L^2 d_{KL} \left( \nu || \mu_\theta  \right).
	\end{align*}
\end{lemma}
\begin{proof}
	Consider any $1$-Lipchitz function $f: \mathbb{R}^d \rightarrow \mathbb{R}$, then $f \circ g_\theta$ is $L$-Lipschitz, which implies $f \circ g_\theta$ is $L^2$-subGaussian due to Gaussian concentration Theorem 3.25 in [CITE:van2014probability]. Therefore we know $f( g_\theta(Z) )$ is $L^2$-subGaussian for any $f$ that is $1$-Lipchitz, together with Theorem 4.8 in [CITE:van2014probability], the proof completes.
\end{proof}

	\begin{lemma}[Theorem 2.5 in [CITE:tsybakov2009introduction]]

		Let $d(\cdot, \cdot)$ be a metric on $\Theta$.
		Assume that $H \geq 2$ and suppose $\Theta$ contains $\theta_0, \theta_1, \ldots, \theta_H$ such that:
		\begin{enumerate}
			\item $d(\theta_j, \theta_k) \geq 2s >0$, for all $j, k \in [H]$ and $j \neq k$.
			\item $\frac{1}{H} \sum_{j=1}^H d_{KL}(P_{j} || P_0) \leq c \cdot\log H$ with $0< c < 1/8$ and $P_j = P_{\theta_j}$ for $j \in [H]$.
		\end{enumerate}
		Then for any estimator $\hat{\theta}$,
		\begin{align*}
			\sup_{\theta \in \Theta} P_\theta(d(\hat{\theta}, \theta) \geq s) \geq \frac{\sqrt{H}}{1+\sqrt{H}} \left( 1 - 2c - \sqrt{\frac{2c}{\log H}} \right) > 0.
		\end{align*}
	\end{lemma}

**Research gap:** Original minimax objective saturates early in training

**Gap description**:
Early in learning, when G is poor, the discriminator can reject samples with high confidence, causing log(1-D(G(z))) to saturate and providing insufficient gradient for G; the authors instead maximize log D(G(z)).

**Canonical description**: generator loss saturates early in training when discriminator is confident

**Paper**: GAN-QP: A Novel GAN Framework without Gradient Vanishing and Lipschitz Constraint

# abstract

We know SGAN may have a risk of gradient vanishing. A significant improvement is WGAN, with the help of 1-Lipschitz constraint on discriminator to prevent from gradient vanishing. Is there any GAN having no gradient vanishing and no 1-Lipschitz constraint on discriminator? We do find one, called GAN-QP.

  To construct a new framework of Generative Adversarial Network (GAN) usually includes three steps: 1. choose a probability divergence; 2. convert it into a dual form; 3. play a min-max game. In this articles, we demonstrate that the first step is not necessary. We can analyse the property of divergence and even construct new divergence in dual space directly. As a reward, we obtain a simpler alternative of WGAN: GAN-QP. We demonstrate that GAN-QP have a better performance than WGAN in theory and practice.

# from_divergence_to_gan

\subsection{Divergence}

Most Generative Adversarial Networks (GANs, [CITE:Goodfellow2014Generative]) are based on a certain form of probability divergence. A divergence is a function $\mathcal{D}$ of two variables $p,q$ satisfies the following definition:
\begin{definition}
If $\mathcal{D}$ is function of two variables $p,q$ satisfies the following properties:
\begin{enumerate}
\item $\mathcal{D}[p, q]\geq 0$;
\item $p = q \Leftrightarrow \mathcal{D}[p, q]=0$.
\end{enumerate}
We say $\mathcal{D}$ is a divergence between $p$ and $q$.
\end{definition}
Compared with the axiomatic defination of distance, a divergence do not need symmetry and triangle inequality necessarily. Divergence only keeps the fundamental property for measuring the difference between $p$ and $q$.

\subsection{Dual Form}

If $p,q$ represent two probability distributions, $\mathcal{D}[p, q]$ becomes a functional and we call it probability divergence. For example, we have Jensen-Shannon divergence (JS divergence):
\begin{equation}\mathcal{JS}[p(x), q(x)] = \frac{1}{2}\int p(x)\log\frac{p(x)}{\frac{1}{2}[p(x)+q(x)]}dx + \frac{1}{2}\int q(x)\log\frac{q(x)}{\frac{1}{2}[p(x)+q(x)]}dx\end{equation}

In most cases, we can find a dual form for a probability divergence [CITE:Nowozin2016f]. For example, the dual form of JS divergence is
\begin{equation}\begin{aligned}\mathcal{JS}[p(x), q(x)] =& \max_T\, \frac{1}{2}\int p(x)\log \sigma(T(x)) dx + \frac{1}{2}\int q(x) \log (1 - \sigma(T(x))) dx + \log 2\\
=& \max_T\, \frac{1}{2}\mathbb{E}_{x\sim p(x)}[\log \sigma(T(x))] + \frac{1}{2}\mathbb{E}_{x\sim q(x)}[\log (1 - \sigma(T(x)))] + \log 2
\end{aligned}\end{equation}
Here $\sigma(x)=1/(1+e^{-x})$ is sigmoid function. The dual form can convert the integral of original divergence into a sampling form, which allows us to estimate it by Monte Carlo method. That is the essential to GAN. The dual form always has a max operation, which means a divergence is a supremum of a family of functions.

\subsection{Min-Max Game}

With the help of dual form of probability divergence, we can train a generator to generate the distribution we are interested via playing a min-max game. For example, using $[REF:eq:js-dual]$ we have
\begin{equation}G,T = \mathop{\arg\min}_G\mathop{\arg\max}_T\, \mathbb{E}_{x\sim p(x)}[\log \sigma(T(x))]+ \mathbb{E}_{x=G(z),z\sim q(z)}[\log (1 - \sigma(T(x)))]\end{equation}
For a fixed $T$, the goal of $G$ is
\begin{equation}\begin{aligned}G =& \mathop{\arg\min}_G \mathbb{E}_{x\sim p(x)}[\log \sigma(T(x))]+ \mathbb{E}_{x=G(z),z\sim q(z)}[\log (1 - \sigma(T(x)))]\\
=& \mathop{\arg\min}_G \mathbb{E}_{x=G(z),z\sim q(z)}[\log (1 - \sigma(T(x)))]\end{aligned}\end{equation}
However, the loss $\log (1 - \sigma(T(x)))$ is not always good for optimization, so we usually use a equivalent loss, such as $-\log \sigma(T(x))$ and $- T(x)$. Namely, we may adjust the loss of generator for a better optimization, rather than playing the original min-max game.

# divergence_in_dual_space

\subsection{Steps to GAN}

From the above discussion, we can see that to construct a GAN usually includes three steps:
\begin{enumerate}
\item choose a probability divergence;
\item onvert it into a dual form;
\item play a min-max game.
\end{enumerate}
But we know that only the last two steps are useful for practice. The fisrt step is only a theoretical concept and is not very important for a GAN. Therefore, a natural thought is: why not analyse the property of divergence and even construct new divergence in dual space directly? Our following content will demonstrate this thought is a very simple approach to build and understand GANs.

\subsection{SGAN}

We start from the Standard GAN (SGAN, [CITE:Goodfellow2014Generative]) as an example to show how we can achieve the goal. From the appendix $[REF:add:js]$, we have Lemma $[REF:lemma:js]$:
\begin{lemma} The following $\mathcal{D}[p(x),q(x)]$ defines a probability divergence
\begin{equation}\mathcal{D}[p(x),q(x)] = \max_T\, \frac{1}{2}\mathbb{E}_{x\sim p(x)}[\log \sigma(T(x))] + \frac{1}{2}\mathbb{E}_{x\sim q(x)}[\log (1 - \sigma(T(x)))] + \log 2\end{equation}
\end{lemma}
It is worth to highlight that we prove $\mathcal{D}[p(x),q(x)]$ is a probability divergence (footnote: Namely, satisfying the definition $[REF:def:div]$.) in dual space, not need the original defination $[REF:eq:js-def]$. Getting rid of the original defination of divergence allows us to seek more powerful divergence in dual space.

Now we have a divergence $\mathcal{D}[p(x),q(x)]$ defined by Lemma $[REF:lemma:js]$, so we can train a generator by minimizing $\mathcal{D}[p(x),q(x)]$, which results in the min-max game $[REF:eq:js-min-max]$.

The difficulty arises while there is almost no intersection between $p(x)$ and $q(x)$. For example, we consider $p(x)=\delta(x-\alpha),q(x)=\delta(x-\beta)$ and $\alpha\neq \beta$. Now we have
\begin{equation}\mathcal{D}[p(x),q(x)]=\max_T\,\frac{1}{2}\log\sigma(T(\alpha)) + \frac{1}{2}\log(1-\sigma(T(\beta)))+\log 2\end{equation}
because no constraint on $T$, we can let $T(\alpha)\to +\infty, T(\beta)\to -\infty$, to obain the maximum value of the above formula, that is
\begin{equation}\mathcal{D}[p(x),q(x)]=\log 2\end{equation}
So if there is almost no intersection between $p(x)$ and $q(x)$, this divergence of them is a constant $\log 2$, whose gradients are zeros. In this situation, generator can not imporve via gradient descent method. And we know this situation will happen with very high probability [CITE:Arjovsky2017Towards]. Therefore it's hard to train a good generative model under the framework of SGAN.

These conclusions can be popularized to any kind of $f$-GANs [CITE:Nowozin2016f] in parallel, including LSGAN [CITE:Mao2016Least]. And all of them suffer the same difficulty.

\subsection{WGAN}

We turn to a new kind of divergence by Lemma $[REF:lemma:wd]$:
\begin{lemma} The following $\mathcal{W}[p(x),q(x)]$ defines a probability divergence
\begin{equation}\mathcal{W}[p(x),q(x)] = \max_{T,\,\Vert T\Vert_L \leq 1}\, \mathbb{E}_{x\sim p(x)}[T(x)] - \mathbb{E}_{x\sim q(x)}[T(x)]\end{equation}
here
\begin{equation}\Vert T\Vert_L = \max_{x\neq y} \frac{|T(x)-T(y)|}{d(x,y)}\end{equation}
and $d(x, y)$ is any distance metric of $x,y$. $d(x,y)=\Vert x-y\Vert_1, d(x,y)=\Vert x-y\Vert_2$ is frequently-used.
\end{lemma}
The proof is in appendix $[REF:add:wd]$. Interestingly, the proof is very simple compared the corresponding proof of $f$-divergence.

Now we can play a new min-max game:
\begin{equation}G,T = \mathop{\arg\min}_G\mathop{\arg\max}_{T,\,\Vert T\Vert_L \leq 1}\, \mathbb{E}_{x\sim p(x)}[T(x)] - \mathbb{E}_{x=G(z),z\sim q(z)}[T(x)]\end{equation}
That is what we call WGAN [CITE:Arjovsky2017Wasserstein].

Compared with $[REF:eq:js-dual-2]$, $\mathcal{W}[p(x),q(x)]$ can reasonably measure the difference of $p(x),q(x)$ while they almost have no intersection. Let us consider $p(x)=\delta(x-\alpha),q(x)=\delta(x-\beta)$ and $\alpha\neq \beta$:
\begin{equation}\mathcal{W}[p(x),q(x)] = \max_{T,\,\Vert T\Vert_L \leq 1} T(\alpha) - T(\beta)\end{equation}
The constraint $\Vert T\Vert_L \leq 1$ means $|T(\alpha) - T(\beta)| \leq d(\alpha, \beta)$. So we have
\begin{equation}\mathcal{W}[p(x),q(x)] = d(\alpha,\beta)\end{equation}
The result is not a constant and its gradients are not zeros. So WGAN will not suffer gradient vanishing usually.

\subsection{WGAN-GP}

The essential problem of WGAN is how to constrain $T$ in $\Vert T\Vert_L \leq 1$, which currently has serveral solutions: weight clipping (WC, [CITE:Arjovsky2017Wasserstein]), gradient penalty (GP, [CITE:Gulrajani2017Improved]) and spectral normalization (SN, [CITE:Miyato2018Spectral]).

Weight clipping is always unstable and has been abandoned in most cases. Spectral normalization is a better operation for not only WGANs but also many other GANs, but it constrains $T$ in a tiny subspace of $\Vert T\Vert_L \leq 1$, wasting the modeling power of $T$. 

It seems the best approch is gradient penalty now. Gradient penalty replaces $\Vert T\Vert_L$ with the norm of gradients $\Vert \nabla_x T\Vert$, and implement it as a penalty term:
\begin{equation}\begin{aligned}&T = \mathop{\arg\max}_T\, \mathbb{E}_{x\sim p(x)}[T(x)] - \mathbb{E}_{x\sim q(x)}[T(x)] - \lambda\mathbb{E}_{x\sim pq(x)}\left[(\Vert \nabla_x T(x)\Vert-1)^2\right]\\
&G = \mathop{\arg\min}_G\, \mathbb{E}_{x=G(z),z\sim q(z)}[-T(x)]
\end{aligned}\end{equation}
whose $\lambda > 0$ is a hyperparameter and $pq(x)$ is the random linear interpolation of $p(x)$ and $q(x)$. It is called WGAN-GP.

WGAN-GP works well in many cases but it is just an empirical trick. Recently some researchs reveal some irrationality of WGAN-GP [CITE:Wu2017Wasserstein]. Another disadvantage of WGAN-GP is the slow speed, while calculating the exact gradients needs more heavy computation.

# gan_with_quadratic_potential

\subsection{A Quadratic Divergence}

From the discussion of SGAN and WGAN, we can see that an ideal divergence should not has any constraints on $T$ (like SGAN) and should give a reasonable measurement of $p(x),q(x)$ while they almost have no intersection (like WGAN). 

Here we propose such a divergence: 
\begin{lemma} The following $\mathcal{L}[p(x),q(x)]$ defines a probability divergence
\begin{equation}\begin{aligned}&\mathcal{L}[p(x),q(x)] \\
=& \max_{T}\, \mathbb{E}_{(x_r,x_f)\sim p(x_r)q(x_f)}\left[T(x_r,x_f)-T(x_f,x_r) - \frac{(T(x_r,x_f)-T(x_f,x_r))^2}{2\lambda d(x_r,x_f)}\right]\end{aligned}\end{equation}
$\lambda > 0$ is a hyperparameter and $d(x_r,x_f)$ is any distance metric of $x_r,x_f$. $d(x_r,x_f)=\Vert x_r-x_f\Vert_1, d(x_r,x_f)=\Vert x_r-x_f\Vert_2$ is frequently-used.
\end{lemma}
The proof is shown in appendix $[REF:add:qp]$. It is like a conventional divergence pluses a quadratic potential, so we call it quadratic potential divergence (QP-div).

Now we check $\mathcal{L}[p(x),q(x)]$ with $p(x)=\delta(x-\alpha),q(x)=\delta(x-\beta)$ to demenstrate QP-div will have a reasonable performance to two extreme distribution:
\begin{equation}\mathcal{L}[p(x),q(x)] = \max_{T}\, T(\alpha,\beta)-T(\beta,\alpha) - \frac{(T(\alpha,\beta)-T(\beta,\alpha))^2}{2\lambda d(\alpha,\beta)}\end{equation}
Let $z = T(\alpha,\beta)-T(\beta,\alpha)$, that is only a maximum value problem of quadratic function $z - \frac{z^2}{2\lambda d(\alpha,\beta)}$. We know it is $\frac{1}{2}\lambda d(\alpha,\beta)$, so
\begin{equation}\mathcal{L}[p(x),q(x)] = \frac{1}{2}\lambda d(\alpha,\beta)\end{equation}
We can see that $\mathcal{L}[p(x),q(x)]$ has similar property like $\mathcal{W}[p(x),q(x)]$, but with no constraints on $T$. It is very friendly to pratice.

\subsection{From QP-div to GAN-QP}

In theory, we can play a min-max game on QP-div to train a generative model
\begin{equation}\begin{aligned}&G,T=\mathop{\arg\min}_G \mathop{\arg\max}_T\, \mathbb{E}_{(x_r,x_f)\sim p(x_r)q(x_f)}\left[\mathscr{L}(x_r, x_f)\right] \\
&\mathscr{L}(x_r, x_f) = T(x_r,x_f)-T(x_f,x_r) - \frac{(T(x_r,x_f)-T(x_f,x_r))^2}{2\lambda d(x_r,x_f)}
\end{aligned}\end{equation}
However, $\mathscr{L}(x_r, x_f)$ is not a good loss for generator because there is a $d(x_r,x_f)$ in the denominator. Generator wants to minmize $\mathscr{L}(x_r, x_f)$, which will minimize $d(x_r,x_f)$ correspondingly. And we know any ready-to-use distance may not be used as a perfect metric of two samples.

We find that using $T(x_r,x_f)-T(x_f,x_r)$ as the loss of generator is enough. That results the following generative model called GAN with Quadratic Potential (GAN-QP):
\begin{equation}\begin{aligned}&T= \mathop{\arg\max}_T\, \mathbb{E}_{(x_r,x_f)\sim p(x_r)q(x_f)}\left[\mathscr{L}(x_r, x_f)\right] \\
&G = \mathop{\arg\min}_G\,\mathbb{E}_{(x_r,x_f)\sim p(x_r)q(x_f)}\left[T(x_r,x_f)-T(x_f,x_r)\right]
\end{aligned}\end{equation}
Futher discussion can be found in appendix $[REF:add:ganqp]$.

\subsection{BiGAN-QP}

Like BiGAN [CITE:Donahue2016Adversarial] or ALI [CITE:Dumoulin2016Adversarially], we can add an inference model $E(x)$ into GAN-QP. Only need to replace $x_r$ with $(x_r, E(x_r))$ and replace $x_f$ with $(G(z), z)$, we have
\begin{equation}\begin{aligned}T&= \mathop{\arg\max}_T\, \mathbb{E}_{x\sim p(x), z\sim q(z)}\left[\Delta T - \frac{\Delta T^2}{2\lambda d\big(x,E(x);G(z),z\big)}\right] \\
G &= \mathop{\arg\min}_{G,E}\,\mathbb{E}_{x\sim p(x), z\sim q(z)}\left[\Delta T\right]\\
\Delta T &= T\big(x,E(x);G(z),z\big)-T\big(G(z),z;x,E(x)\big)
\end{aligned}\end{equation}
That is what we called BiGAN-QP. In theory, $[REF:eq:bigan-gp-gd]$ is enough for training the whole model. But actually it is hard to converge. We need to add some guiding term to guide the training process. We can use reconstruction mse loss as the guiding term:
\begin{equation}\begin{aligned}T&= \mathop{\arg\max}_T\, \mathbb{E}_{x\sim p(x), z\sim q(z)}\left[\Delta T - \frac{\Delta T^2}{2\lambda d\big(x,E(x);G(z),z\big)}\right] \\
G &= \mathop{\arg\min}_{G,E}\,\mathbb{E}_{x\sim p(x), z\sim q(z)}\Big[\Delta T + \beta_1 \Vert z - E(G(z))\Vert^2 + \beta_2 \Vert x - G(E(x))\Vert^2\Big]\\
\Delta T &= T\big(x,E(x);G(z),z\big)-T\big(G(z),z;x,E(x)\big)
\end{aligned}\end{equation}
In practice, we find the following altering can improve quality of reconstruction:
\begin{equation}\begin{aligned}T&= \mathop{\arg\max}_T\, \mathbb{E}_{x\sim p(x), z\sim q(z)}\left[\Delta T - \frac{\Delta T^2}{2\lambda d\big(x,E(x);G(z),z\big)}\right] \\
G &= \mathop{\arg\min}_{G,E}\,\mathbb{E}_{x\sim p(x), z\sim q(z)}\Big[\Delta T + \beta_1 \Vert z - E(G_{ng}(z))\Vert^2 + \beta_2 \Vert x - G(E_{ng}(x))\Vert^2\Big]\\
\end{aligned}\end{equation}
where $G_{ng}$ and $E_{ng}$ means we stop its gradient at its output.

# experiments

\subsection{Experimential Details}

Our experiments are mainly conducted on CelebA HQ dataset [CITE:Karras2017Progressive]. Our basic setup follows DCGANs [CITE:Radford2015Unsupervised], and is implemented in Keras [CITE:chollet2015keras], and available in my repository\footnote{\url{https://github.com/bojone/gan-qp}}. We use the Adam optimizer [CITE:Kingma2014Adam], with a constant learning rate of $2\times 10^{-4}$ and $\beta_1 = 0.5, \beta_2 = 0.999$ in both $T$ and $G$. We train GAN-QP with two D steps per G step.

In $[REF:eq:gan-gp-gd]$, discriminator $T$ is a model with both real sample $x_r$ and fake sample $x_f$ as inputs. But in our experiments, we find just using one sample as input has generated good performance. In other words, $T(x_r,x_f)\equiv T(x_r)$ is enough. We try the architecture like $T(x_r, x_f)=D([E(x_r), E(x_f)])$ but there is no obvious improvement. So the final loss we use is
\begin{equation}\begin{aligned}&T= \mathop{\arg\max}_T\, \mathbb{E}_{(x_r,x_f)\sim p(x_r)q(x_f)}\left[T(x_r)-T(x_f) - \frac{(T(x_r)-T(x_f))^2}{2\lambda d(x_r,x_f)}\right] \\
&G = \mathop{\arg\min}_G\,\mathbb{E}_{(x_r,x_f)\sim p(x_r)q(x_f)}\left[T(x_r)-T(x_f)\right]
\end{aligned}\end{equation}

Hyperparameter $\lambda$ is
\begin{equation}\lambda = \left\{\begin{aligned}&\frac{10}{w\times h\times ch},\,\text{while } d(x_r,x_f)=\Vert x_r-x_f\Vert_1\\
&\frac{10}{\sqrt{w\times h\times ch}},\,\text{while } d(x_r,x_f)=\Vert x_r-x_f\Vert_2  \end{aligned}
\right.\end{equation}
$w,h,ch$ is the width, height and the number of channels of the input images.We test both L1 norm $d(x_r,x_f)=\Vert x_r-x_f\Vert_1$ and L2 norm $d(x_r,x_f)=\Vert x_r-x_f\Vert_2$ in our experiments, but they have no significant statistical difference.

The quantitative index we use to evaluate a GAN is Frechet Inception Distance (FID, [CITE:Heusel2017GANs]). We also re-implement it in Keras.

\subsection{Basic Comparison}

Firstly, we compared GAN-QP with WGAN-GP, WGAN-SN (WGAN with spectral normalization), SGAN-SN (SGAN with spectral normalization), LSGAN-SN (LSGAN with spectral normalization) on 128x128 resolution. $\lambda$ in WGAN-GP $[REF:eq:wgan-gp]$ we use is 10. Then Batch Normalization is removed from discriminator of WGAN-GP and other hyperparameters are as the same as GAN-QP. Each experiment is repeated twice for obtaining more reliable conclusion. The comparison is shown in Figure $[REF:fig:fid-comparison]$ and Table $[REF:tab:128-3]$. 

We can see that there is no obvious difference between GAN-QP-L1 and GAN-QP-L2, which means GAN-QP is robust to distance metric. The best two results come from GAN-QP and WGAN-SN. The worst is WGAN-GP. Generally, the FID curve of WGAN-SN and SGAN-SN is more smoother and GAN-QP is more shaking. But GAN-QP keeps the best performance as same as SGAN-SN.

