# detailed_derivation

\subsection{$[REF:eq:js-dual-2]$ is a divergence}

Firstly, it is trivial to see that $\mathcal{D}[p(x), q(x)]$ is nonnegative since we can always let $T(x)\equiv 0$:
\begin{equation}\begin{aligned}\mathcal{D}[p(x),q(x)] =& \max_T\, \frac{1}{2}\mathbb{E}_{x\sim p(x)}[\log \sigma(T(x))] + \frac{1}{2}\mathbb{E}_{x\sim q(x)}[\log (1 - \sigma(T(x)))] + \log 2\\
\geq& \frac{1}{2}\mathbb{E}_{x\sim p(x)}[\log \sigma(0)] + \frac{1}{2}\mathbb{E}_{x\sim q(x)}[\log (1 - \sigma(0))] + \log 2\\
=& 0
\end{aligned}\end{equation}

Next, we show $\mathcal{D}[p(x), p(x)]=0$, which is also simple:
\begin{equation}\begin{aligned}\mathcal{D}[p(x),p(x)] =& \max_T\, \frac{1}{2}\mathbb{E}_{x\sim p(x)}[\log \sigma(T(x)) + \log (1 - \sigma(T(x)))] + \log 2\\
=& \max_T\, \frac{1}{2}\mathbb{E}_{x\sim p(x)}[\log \big(\sigma(T(x))(1 - \sigma(T(x)))\big)] + \log 2
\end{aligned}\end{equation}
It is not difficult to prove that the maximum value of $\sigma(z)(1-\sigma(z))$ is $\frac{1}{4}$ at $z=0$, so we have
\begin{equation}\mathcal{D}[p(x),p(x)] = \frac{1}{2}\mathbb{E}_{x\sim p(x)}[\log \frac{1}{4}] + \log 2 = 0\end{equation}

Finally, we show $\mathcal{D}[p(x), q(x)] > 0$ if $p(x)\neq q(x)$.\footnote{Strictly, $p(x)\neq q(x)$ is not enough. The sufficient condition is $\int_{\{x|p(x)\neq q(x)\}}dx > 0$.} Let
\begin{equation}\sigma(T(x))=\frac{p(x)}{p(x)+q(x)}=\lambda(x)\end{equation}
we have
\begin{equation}\begin{aligned}\mathcal{D}[p(x),q(x)]=&\frac{1}{2}\int \left[p(x)\log \frac{p(x)}{p(x)+q(x)} + q(x) \log \frac{q(x)}{p(x)+q(x)}\right]dx+\log 2\\
=&\int \left(\frac{p(x)+q(x)}{2}\right)\Big[\lambda(x)\log \lambda(x) + \big(1-\lambda(x)\big)\log \big(1-\lambda(x)\big)\Big]dx+\log 2\end{aligned}\end{equation}
Becausce of $p(x)\neq q(x)$, $\lambda(x)\not\equiv 1/2$, and we know $\lambda \log \lambda + (1-\lambda)\log(1-\lambda) < -\log 2$ if $\lambda\neq \frac{1}{2}$. Therefore,
\begin{equation}\mathcal{D}[p(x),q(x)] > \int \left(\frac{p(x)+q(x)}{2}\right)(-\log 2)dx+\log 2 = 0\end{equation}

\subsection{$[REF:eq:wd-dual]$ is a divergence}

Firstly, it is trivial to see that $\mathcal{W}[p(x), q(x)]$ is nonnegative since we can always let $T(x)\equiv 0$:
\begin{equation}\mathcal{W}[p(x),q(x)] \geq \mathbb{E}_{x\sim p(x)}[0] - \mathbb{E}_{x\sim q(x)}[0] = 0\end{equation}

Next, $\mathcal{W}[p(x), p(x)]=0$ is also trivial. So we only need to show $\mathcal{W}[p(x), q(x)] > 0$ if $p(x)\neq q(x)$. It it actually not difficult because we only need to let $T_0(x) = \text{sign}(p(x) - q(x))$:
\begin{equation}\mathbb{E}_{x\sim p(x)}[T_0(x)] - \mathbb{E}_{x\sim q(x)}[T_0(x)] =\int (p(x)-q(x))\cdot\text{sign}(p(x) - q(x))dx > 0\end{equation}
That means $\mathcal{W}[p(x), p(x)] > 0$.

\subsection{$[REF:eq:qp-dual]$ is a divergence}

Firstly, it is trivial to see that $\mathcal{W}[p(x), q(x)]$ is nonnegative since we can always let $T(x_r, x_f)\equiv 0$:
\begin{equation}\mathcal{L}[p(x),q(x)] \geq \mathbb{E}_{(x_r,x_f)\sim p(x_r)q(x_f)}\left[0 - \frac{0^2}{2\lambda d(x,y)}\right]=0\end{equation}

Next, we have
\begin{equation}\begin{aligned}\mathcal{L}[p(x),p(x)] = & \max_{T}\, \mathbb{E}_{(x_r,x_f)\sim p(x_r)p(x_f)}\left[-\frac{(T(x_r,x_f)-T(x_f,x_r))^2}{2\lambda d(x,y)}\right]\end{aligned}\end{equation}
Obviously, the maximum value is zero. So $\mathcal{L}[p(x),p(x)]=0$.

Finally, if $p(x)\neq q(x)$, we let
\begin{equation}T_0(x_r, x_f) = \text{sign}(p(x_r)q(x_f) - p(x_f)q(x_r))\end{equation}
now we have
\begin{equation}\begin{aligned}\gamma_1 = &\mathbb{E}_{(x_r,x_f)\sim p(x_r)q(x_f)}\left[T_0(x_r,x_f)-T_0(x_f,x_r)\right] \\
=&\iint p(x_r)q(x_f) \left[T_0(x_r,x_f)-T_0(x_f,x_r)\right] dx_r dx_f\\
=&\iint \left[p(x_r)q(x_f) - p(x_f)q(x_r)\right] T_0(x_r,x_f) dx_r dx_f\\
=&\iint \left[p(x_r)q(x_f) - p(x_f)q(x_r)\right] \cdot \text{sign}(p(x_r)q(x_f) - p(x_f)q(x_r)) dx_r dx_f > 0\\
\gamma_2=&\mathbb{E}_{(x_r,x_f)\sim p(x_r)q(x_f)}\left[\frac{(T_0(x_r,x_f)-T_0(x_f,x_r))^2}{2\lambda d(x,y)}\right] \geq 0\end{aligned}\end{equation}
If $\gamma_1 > \gamma_2$, then
\begin{equation}\begin{aligned}&\mathbb{E}_{(x_r,x_f)\sim p(x_r)q(x_f)}\left[T(x_r,x_f)-T(x_f,x_r) - \frac{(T(x_r,x_f)-T(x_f,x_r))^2}{2\lambda d(x,y)}\right]\\
=&\gamma_1 - \gamma_2 > 0\end{aligned}\end{equation}
else if $\gamma_1 \leq \gamma_2$, we can define
\begin{equation}T(x_r, x_f) = \frac{\gamma_1}{2\gamma_2}\cdot T_0(x_r, x_f)\end{equation}
then
\begin{equation}\begin{aligned}&\mathbb{E}_{(x_r,x_f)\sim p(x_r)q(x_f)}\left[T(x_r,x_f)-T(x_f,x_r) - \frac{(T(x_r,x_f)-T(x_f,x_r))^2}{2\gamma d(x,y)}\right]\\
=&\left(\frac{\gamma_1}{2\gamma_2}\right)\gamma_1 - \left(\frac{\gamma_1}{2\gamma_2}\right)^2\gamma_2 = \frac{\gamma_1^2}{4\gamma_2} > 0\end{aligned}\end{equation}

Therefore $\mathcal{L}[p(x),q(x)] > 0$.

# analyse_of_gan_qp

\subsection{Optimum Solution of $[REF:eq:qp-dual]$}

\begin{lemma} the optimum solution of $[REF:eq:qp-dual]$ satisfies
\begin{equation}\frac{p(x_r)q(x_f) - p(x_f)q(x_r)}{p(x_r)q(x_f) + p(x_f)q(x_r)} = \frac{T(x_r,x_f)-T(x_f,x_r)}{\lambda d(x_r, x_f)}\end{equation}
\end{lemma}

The proof is the basic application of variational method:
\begin{equation}\begin{aligned}&\delta\iint p(x_r)q(x_f)\left[T(x_r,x_f)-T(x_f,x_r) - \frac{(T(x_r,x_f)-T(x_f,x_r))^2}{2\lambda d(x_r,x_f)}\right]dx_r dx_f\\
=&\iint p(x_r)q(x_f)\Bigg[\delta T(x_r,x_f)-\delta T(x_f,x_r)\\
&\qquad\qquad\qquad\qquad- \frac{(T(x_r,x_f)-T(x_f,x_r))(\delta T(x_r,x_f)-\delta T(x_f,x_r))}{\lambda d(x_r,x_f)}\Bigg]dx_r dx_f\\
=&\iint \Bigg[p(x_r)q(x_f) - p(x_f)q(x_r) \\
&\qquad\qquad\qquad\qquad- \Big(p(x_r)q(x_f) + p(x_f)q(x_r)\Big)\frac{T(x_r,x_f)-T(x_f,x_r)}{\lambda d(x_r,x_f)}\Bigg]\delta T(x_r,x_f)dx_r dx_f\\
\end{aligned}\end{equation}
The formula in square brackets must be identically equal to zero. Therefore
\begin{equation}\frac{p(x_r)q(x_f) - p(x_f)q(x_r)}{p(x_r)q(x_f) + p(x_f)q(x_r)} = \frac{T(x_r,x_f)-T(x_f,x_r)}{\lambda d(x_r, x_f)}\end{equation}

\subsection{Adaptive Lipschitz Constraint}

From $[REF:eq:opt-t]$, it is not difficult to prove that the optimum $T(x_r, x_f)$ satisfies
\begin{equation}-1 \leq \frac{T(x_r,x_f)-T(x_f,x_r)}{\lambda d(x_r, x_f)}\leq 1\end{equation}
In other words, the optimum $T(x_r, x_f)$ satisfies Lipschitz constraint automatically. Therefore we can say $[REF:eq:qp-dual]$ is a divergence with adative Lipschitz constraint.

\subsection{The Divergence of Generator}

We use $T(x_r,x_f)-T(x_f,x_r)$ rather than the whole $\mathscr{L}(x_r, x_f)$ as the loss of generator in $[REF:eq:gan-gp-gd]$. And we have solved the optimum solution of $[REF:eq:qp-dual]$ in Lemma $[REF:lemma:opt]$. Then we can see the ultimate goal of generator to minimize is
\begin{equation}\lambda \iint p(x_r)q(x_f)\frac{p(x_r)q(x_f) - p(x_f)q(x_r)}{p(x_r)q(x_f) + p(x_f)q(x_r)} d(x_r, x_f) dx_r dx_f \end{equation}
Now we have Lemma $[REF:lemma:opt-g]$:
\begin{lemma}
\begin{equation}\tilde{\mathcal{L}}[p(x),q(x)]=\iint p(x_r)q(x_f)\frac{p(x_r)q(x_f) - p(x_f)q(x_r)}{p(x_r)q(x_f) + p(x_f)q(x_r)} d(x_r, x_f) dx_r dx_f\end{equation}
is also a probability divergence of $p(x),q(x)$.
\end{lemma}

Actually Lemma $[REF:lemma:opt-g]$ is a conclusion of Cauchy–Schwarz inequality. Firstly we let
\begin{equation}\mu(x_r, x_f) = \frac{d(x_r, x_f)}{p(x_r)q(x_f) + p(x_f)q(x_r)} > 0\end{equation}
Then by Cauchy–Schwarz inequality we have
\begin{equation}\begin{aligned}&\left(\iint \mu(x_r, x_f) p^2(x_r) q^2(x_f) dx_r dx_f\right)^2\\
= &\left(\iint \left(\sqrt{\mu(x_r, x_f)} p(x_r) q(x_f)\right)^2 dx_r dx_f\right)\left(\iint \left(\sqrt{\mu(x_f, x_r)} p(x_f) q(x_r)\right)^2 dx_f dx_r\right)\\
\geq & \left(\iint \mu(x_r, x_f) p(x_r) q(x_f) p(x_f) q(x_r) dx_r dx_f\right)^2
\end{aligned}\end{equation}
So
\begin{equation}\tilde{\mathcal{L}}[p(x),q(x)] = \iint \mu(x_r, x_f) p(x_r) q(x_f) \Big(p(x_r) q(x_f) - p(x_f) q(x_r)\Big) \mu(x_r, x_f) dx_r dx_f\geq 0\end{equation}
Two sides are equal if and only if $\sqrt{\mu(x_r, x_f)} p(x_r) q(x_f)\equiv \sqrt{\mu(x_f, x_r)} p(x_f) q(x_r)$, which means $p(x)\equiv q(x)$. Therefore $[REF:eq:opt-g-loss]$ is a probability divergence, which means to lower $T(x_r,x_f)-T(x_f,x_r)$ is actually to lower the difference between $p(x)$ and $q(x)$. The divergence is weighted by $d(x_r, x_f)$, forcing generator to focus on the sample pairs of larger distance, which is in line with our intuition.

\subsection{Performance while No Intersection}

We have shown the QP-div in Lemma $[REF:lemma:qp]$ also works well while there is no intersection between $p(x)$ and $q(x)$. But now we use $T(x_r,x_f)-T(x_f,x_r)$ as the loss of generator, corresponding to the new divergence $\tilde{\mathcal{L}}[p(x),q(x)]$. Therefore we have to check the performance of $\tilde{\mathcal{L}}[p(x),q(x)]$ with $p(x)=\delta(x-\alpha),q(x)=\delta(x-\beta)$. That is very easy:
\begin{equation}\begin{aligned}&\tilde{\mathcal{L}}[\delta(x-\alpha),\delta(x-\beta)]\\
=&\iint \delta(x_r-\alpha)\delta(x_f-\beta)\frac{\delta(x_r-\alpha)\delta(x_f-\beta) - \delta(x_f-\alpha)\delta(x_r-\beta)}{\delta(x_r-\alpha)\delta(x_f-\beta) + \delta(x_f-\alpha)\delta(x_r-\beta)} d(x_r, x_f) dx_r dx_f\\
=&\frac{\delta(0)\delta(0) - \delta(\beta-\alpha)\delta(\alpha-\beta)}{\delta(0)\delta(0) + \delta(\beta-\alpha)\delta(\alpha-\beta)} d(\alpha, \beta)
\end{aligned}\end{equation}
We know $\delta(0)\to\infty$ and $\delta(\alpha-\beta)=0$ for $\alpha\neq\beta$, so the result is $d(\alpha, \beta)$, a reasonable measurement actually.

\subsection{Robustness of $\lambda$}

$[REF:eq:gan-qp-g-loss]$ showed that $\lambda$ is just a scaler for $\tilde{\mathcal{L}}[p(x),q(x)]$. That means GAN-QP is insensitive to the hyperparameter $\lambda$, which is different from WGAN-GP. We only need to choose a suitable $\lambda$ to make the loss more readable (not very large and not very small).

