\subsection{Proof of Theorem [REF:theorem1]}



The dissipation rate:
For any curve $\{q_t\}_{t \geq 0}$ evolving according to the vector field $\{v_t\}_{t\geq 0}$, the dissipation rate of the functional [CITE:ambrosio2005gradient] is given as 
\begin{equation}
    \frac{\partial\mathcal{F}(q_t)}{\partial t} = \int {\langle \nabla_{W_2} {\mathcal{F}(q_t)}, v_t \rangle} \mathrm{d}q_t.
\end{equation}
If the functional is the KL divergence, we have the associated Wasserstein gradient  $\nabla_{W_2} {\mathcal{F}(q_t)} = \gradx \log (q_t/p)$. Recall that the vector filed of MonoFlow in Eq.~([REF:mono gf]) is 
\begin{equation}
    v_t = h'(\log r_t)\nabla_{\rvx} \log r_t, \quad r_t = \log (p/q_t)
\end{equation}

Therefore, if $h'(\cdot) > 0$, MonoFlow dissipates the KL divergence with the rate
\begin{equation}
     \frac{\partial\mathcal{F}(q_t)}{\partial t} = \mathbb{E}_{\rvx \sim q_t}\left[-h'\big(\log r_t (\rvx) \big){\left\lVert\gradx \log  \frac{q_t(\rvx)}{p(\rvx)} \right\rVert^2}\right] \leq 0.
\end{equation}
It is obvious that  ${\partial\mathcal{F}(q_t)}/{\partial t} =0 $ implies 
\begin{equation}
    \mathbb{E}_{\rvx \sim q_t}\left[{\big\lVert\gradx \log  q_t(\rvx) - \gradx\log  p(\rvx)\big\rVert^2}\right] = 0,
\end{equation}
where the left hand side is the Fisher divergence $\mathcal{D}_{{FI}}(q_t||p)$. If $p$ is a well defined proper probability measure on $\mathbb{R}^n$, $\mathcal{D}_{{FI}}(q_t||p)$ attains zero if and only if $q_t=p$.

 Hence, MonoFlow always decreases the KL divergence with the time when $q_t\neq p$. By the monotone convergence theorem, i.e., any decreasing sequence converges to its infimum, thus the KL divergence converges to zero if $t\to \infty$, which indicates $q_t$ evolves to $p$.

\subsection{Proof of Theorem [REF:theorem2]}

Define the functional $\gF(q)$ of $f$-divergences as
\begin{equation}
\gF(q) = \mathcal{D}_f(p||q) = \int f\left(\frac{p}{q}\right)(\rvx) q(\rvx)\mathrm{d}\rvx.
\end{equation}
where $f\colon \mathbb{R}^+ \to \mathbb{R}$ is a convex function and we may further assume that $f$ is twice differentiable.

Let $\phi \in \mathcal{P}(\mathbb{R}^n) $ be a test function, the first variation (functional derivative) $\frac{\delta \gF}{\delta q}$ is defined as
\begin{equation}
\begin{split}
\int \frac{\delta \gF}{\delta q} (\rvx) \phi(\rvx) \mathrm{d}\rvx &= \lim_{\epsilon \to 0} \frac{\gF(q+\epsilon\phi)- \gF(q) }{\epsilon} \\
&=\frac{d}{d\epsilon} \gF(q+\epsilon\phi)\Big \vert_{\epsilon=0}\\
& = \frac{d}{d\epsilon} \int f\left(\frac{p}{q+\epsilon\phi}\right)(\rvx)\big(q(\rvx)+\epsilon\phi(\rvx)\big) \mathrm{d}\rvx\Big \vert_{\epsilon=0} \\
&=  \int  \left\{f\left(\frac{p}{q+\epsilon\phi}\right) (\rvx) \phi(\rvx)- f'\left(\frac{p}{q+\epsilon\phi}\right)(\rvx) \frac{p(\rvx) \phi(\rvx)}{q(\rvx)+\epsilon\phi(\rvx)} \right\} \mathrm{d}\rvx   \Big \vert_{\epsilon=0} \\
&=  \int  \left\{f\left(\frac{p}{q}\right) - f'\left(\frac{p}{q}\right) \frac{p}{q} \right\} (\rvx)\phi(\rvx) \mathrm{d}\rvx.  \\
\end{split}
\end{equation}
Thus,
\begin{equation}
\frac{\delta \gF}{\delta q} = f(r) - rf'(r), \quad \text{where} \quad r = \frac{p}{q} .
\end{equation}
Recall that the Wasserstein gradient of $\gF(q)  $ is the Euclidean gradient of the first variation, we have 
\begin{equation}
\nabla_{W_2} \gF(q) = \gradx \frac{\delta \gF}{\delta q} = - r f''(r) \gradx r.
\end{equation}
The corresponding vector field is given by the negative Euclidean gradient, see Section [REF:wgf], therefore the particle flow ODE of $f$-divergences can be written as  
\begin{equation}
\mathrm{d}\rvx = -\gradx \frac{\delta \gF}{\delta q}(\rvx)\mathrm{d}t  = r(\rvx) f''(r(\rvx)) \gradx r(\rvx)\mathrm{d}t = r(\rvx)^2 f''(r(\rvx)) \gradx \log r(\rvx)\mathrm{d}t.
\end{equation}

\subsection{Proof of Corollary 3.3}

According to the existence theorem of primitive functions (antiderivative), any  continuous scalar function must have a primitive function and this primitive function is also continuous. Hence, if $f''(r) = h'(\log r) /r^2$ where $h$ is continuously differentiable, we have $f''(r)$ is continuous such that $f'(r)$ and $f(r)$ both exist. We also have $h'(\log r)>0\Longrightarrow f''(r)>0$, this indicates $f$ is strictly convex. 

Hence, given a differentiable $h$ with $h'(\cdot) > 0$, there must exist a strictly convex function $f$ such that $f(1)=0$ (primitive functions differ in constants) where its second derivative is specified by $f''(r) = h'(\log r) /r^2$.

We can let $h(\log r) = rf'(r) - f(r)+C$, apparently $h(\log r) = rf'(r) - f(r)+C \Longleftrightarrow h'(\log r) = r^2f''(r)$, this defines the particle evolution of Wasserstein gradient flows, 
\begin{equation}
    \mathrm{d}\rvx_t 
     = h'\big(\log r_t(\rvx_t)\big)\nabla_{\rvx} \log r_t(\rvx_t) \mathrm{d}t = r(\rvx_t)^2f''\big(r(\rvx_t)\big)\nabla_{\rvx} \log r_t(\rvx_t) \mathrm{d}t.
\end{equation}
 Without the loss of generality, we can let $h(\log r) = rf'(r) - f(r)$.

\subsection{Proof of Lemma 3.4} 

This proof is adapted from Lemma 1 and 2 of [CITE:moustakides2019training].
Given the optimization problem
\begin{equation}
\max_{d \in \mathcal{H}} \ \mathbb{E}_{\rvx\sim p}\left[\phi\big(d(\rvx)\big)\right] + \mathbb{E}_{\rvx\sim q}\left[\psi \big( d(\rvx)\big)\right],
\end{equation}
where $\mathcal{H}$ is a class of all measurable functions.
We rewrite it as 
\begin{equation}
\begin{split}
& \max_{d \in \mathcal{H}} \  \mathbb{E}_{\rvx\sim q}\left[\frac{p(\rvx)}{q(\rvx)} \phi\big(d(\rvx)\big) + \psi \big( d(\rvx)\big)\right] \\
&= \mathbb{E}_{\rvx\sim q}\left[\max_{d \in \mathcal{H}} \left\{\frac{p(\rvx)}{q(\rvx)} \phi\big(d(\rvx)\big) + \psi \big( d(\rvx)\big) \right\} \right], 
\end{split}
\end{equation}
we apply the interchange of maximum and integral because the integral operator is independent of $d$.  
Since the maximum is holding for every fixed $\rvx$, thus we let the derivative $\frac{\partial }{\partial d(\rvx)} \left[\frac{p(\rvx)}{q(\rvx)} \phi\big(d(\rvx)\big) + \psi \big( d(\rvx)\big)\right] = 0$, we have the optimal $d^\ast$, the abbreviation of $d^\ast(\rvx)$, to satisfy
\begin{equation}
r\phi'(d^\ast) + \psi' (d^\ast) = 0, \quad r(\rvx) = \frac{p(\rvx)}{q(\rvx)} >0 
\end{equation}

Furthermore, we need to discuss under what sufficient conditions, $d^\ast$ is the unique maximizer for the above problem. Denote $l(d) = r\phi(d) + \psi(d)$, in order to ensure that $d^\ast$ is the unique maximizer, $l'(d)$ should satisfy 
\begin{equation}
l'(d)>0, \forall d<d^\ast \text{ and } l'(d)<0, \forall d>d^\ast.  
\end{equation}
We define the mapping $\mathcal{T}(d) : = -\frac{\psi'(d)}{\phi' ( d) }$ and summarize two sufficient conditions as:
\begin{enumerate}
    \item $\phi$ is concave, $\psi$ is strictly concave and the resulting mapping $\mathcal{T}$ is a bijection.
    \item $\phi'(\cdot) >0 $ and the resulting mapping $\mathcal{T}$ is a strictly increasing mapping (also a bijection).
\end{enumerate}
It is obvious that if $\mathcal{T}$ is a bijection, $d^\ast=\mathcal{T}^{-1}(r)$ is the root of Eq.~([REF:ratioEq.]).

For condition 1, since $\phi$ is concave and $\psi$ is strictly concave, the linear combination $l(d)$ is strictly concave which satisfies Eq.~([REF:condi]). Therefore, $d^\ast$ is the unique maximizer. 

For condition 2, we can write $l'(d) = [\mathcal{T} (d^*) - \mathcal{T} (d) ]\phi'(d)$. Since $\mathcal{T}$ is a strictly increasing mapping and $d^*$ is the maximizer, we have $\mathcal{T} (d^*) - \mathcal{T} (d)>0$ for $d<d^\ast$ and $\mathcal{T} (d^*) - \mathcal{T} (d)<0$ for $d>d^\ast$. Hence $l'(d)$ satisfies the condition stated in Eq.~([REF:condi]).

In Table [REF:table_1], $b$-gan satisfies condition 2 and the rest of the divergence GANs satisfy condition 1.

Some examples:
\begin{itemize}
    \item For binary classification, $\phi(d) = \log \sigmoid(d)$ and $\psi(d) = \log (1-\sigmoid(d))$, $r(\rvx)=\exp(d^*(\rvx))$.
    \item Fenchel-duality, $\phi(d) = d $, $\psi(d)=-\tilde{f}(d) $, $r(\rvx) = {\tilde{f}}' \big(d^*(\rvx)\big)$ where the convex conjugate is $\tilde{f}(d) = \sup_{r\in\text{dom}f}\{rd - f(r)\}$
    \item For least-square GAN, $\phi(d) = -(d -1) ^2, \psi(d)=-d^2$, $r(\rvx) = \frac{d^*(\rvx)}{1-d^*(\rvx)}$
\end{itemize}

# variational_divergence_minimization

Given an $f$-divergence $\mathcal{D}_f(p||q)$ where $p$ is the fixed target distribution, variational divergence minimization finds an approximating distribution $q$ via the functional optimization
\begin{equation}
\min_q \mathcal{D}_f(p||q).
\end{equation}
If $q$ is represented by a parametric model with an explicit density function $q(\rvx;\theta)$, the $f$-divergence can be written as 
\begin{equation}
\text{Cost}(\theta) = \mathcal{D}_f(p||q) =  \int f\big(  r(\rvx, \theta) \big) q(\rvx;\theta)\mathrm{d}\rvx
\end{equation}
where $r(\rvx, \theta) = {p(\rvx)}/{q(\rvx;\theta)}$ explicitly depends on $\rvx$ and $\theta$. The $f$-divergence becomes a cost function of the parameter $\theta$ because $\rvx$ is integrated out. A typical example is in standard variational inference where $q$ is a parametric Gaussian distribution such that we know the exact density function $q(\rvx;\theta)$. 

Hence, the functional optimization problem degenerates into an optimization problem over the parameter space, 
\begin{equation}
\min_q \mathcal{D}_f(p||q) \Longleftrightarrow \min_{\theta} \text{Cost}(\theta). 
\end{equation}

Since $f$ is convex, we can apply Jensen's inequality, 
\begin{equation}
\mathcal{D}_f(p||q) = \int f\left( \frac{p(\rvx)}{q(\rvx;\theta)} \right) q(\rvx;\theta)\mathrm{d}\rvx  \geq f\left(\int \frac{p(\rvx)}{q(\rvx;\theta)} q(\rvx;\theta) \mathrm{d}\rvx \right) =f(1)=0,
\end{equation}
Jensen's inequality indicates that $\mathcal{D}_f(p||q)=0$ if and only if ${p(\rvx)}/{q(\rvx;\theta)}$ is a constant, such that we have $q=p$.\\\\
Therefore, we can minimize the cost function $\text{Cost}(\theta)$ to approximate $p$ with $q$. Solving the optimization problem in Eq.~([REF:vdm_cost]) requires Monte Carlo gradient estimation, we can apply the reparameterization trick [CITE:kingma2013auto] [CITE:rezende2014stochastic] to solve 
\begin{equation}
    \min_\theta \text{Cost}(\theta)= \min_\theta \mathbb{E}_{\rvz \sim p_{\rvz}} \big[f\big(r(\rvx_\theta(\rvz), \theta)\big)\big], \text{ where } \rvx_\theta(\rvz) = g_\theta(\rvz).
\end{equation}
 $g_\theta$ is the Gaussian generator parameterized by $\theta$. The associated gradient estimation is obtained by the chain rule, 
 \begin{equation}
 \mathbb{E}_{\rvz \sim p_{\rvz}}  \big[\nabla_{\theta} f(r(\rvx_\theta(\rvz), \theta))\big] =  \mathbb{E}_{\rvz \sim p_{\rvz}} \big[f'(r(\rvx_\theta(\rvz), \theta))(\frac{\partial r}{\partial \rvx_\theta} \frac{\partial \rvx_\theta}{ \partial\theta} + \frac{\partial r}{\partial \theta})\big]
 \end{equation}
 if we detach the gradient of $\theta$ in the ratio model, the gradient estimation is distorted,
  \begin{equation}
 \mathbb{E}_{\rvz \sim p_{\rvz}}  \big[\nabla_{\theta} f(r(\rvx_\theta(\rvz), \theta_{\text{de}}))\big] =  \mathbb{E}_{\rvz \sim p_{\rvz}} \big[f'(r(\rvx_\theta(\rvz), \theta_{\text{de}}))(\frac{\partial r}{\partial \rvx_\theta} \frac{\partial \rvx_\theta}{ \partial\theta} )\big].
 \end{equation}


 Alternatively, we can apply score function gradient estimation, see [CITE:mohamed2019monte] for more details.

