\begin{algorithm}
    \caption{Simplified Sampling for PGMs}
    \begin{algorithmic}[1]
    \State Input: Batch size BS, number of steps K, model length L, special BOS index
    \State Output: Generated samples x

    \State x $\gets$ empty\_tensor(BS, 1) \Comment{{ Initialize}}
    \State x[:, 0] $\gets$ BOS \Comment{{ Set BOS as first token}}
    \State k $\gets$ L/K \Comment{{ Number of tokens to denoise at each step}}
    \State decoded\_positions $\gets$ zeros(BS, 1) \Comment{{ Keep track of already-decoded and positions to decode}}
    \State positions\_to\_decode $\gets$ $1 + $ rand\_row\_perm(BS, L-1) \Comment{{ Each rows is a permutation of $\{1, ..., L\}$}}

    \For{\_ in range(K)}
        \State pos\_to\_decode $\gets$ positions\_to\_decode[:, :k] \Comment{{ Random positions to be predicted}}
        \State new\_values $\gets$ pgm\_predict(x, decoded\_positions, pos\_to\_decode) 
        \State $x \gets$ concat([x, new\_values], dim=1) \Comment{{ Add new values to the sequence length dimension}}
        \State decoded\_positions $\gets$ concat([decoded\_positions, pos\_to\_decode], dim=1)
        \State positions\_to\_decode $\gets$ positions\_to\_decode[:, k:] \Comment{{ Remove the k decoded positions}}
    \EndFor

    \State out $\gets$ reorder(x, decoded\_positions) \Comment{{ Sort based on positions}}
    \State \Return out
    \end{algorithmic}

    \end{algorithm}


\begin{algorithm}[t]
    \caption{MDLM-equivalent sampling for PGMs.}
    \begin{algorithmic}[1]
    \State Input: Batch size BS, number of steps K, model length L, special BOS index
    \State Output: Generated samples x

    \State x $\gets$ empty\_tensor(BS, 1) \Comment{ { Initialize}}
    \State x[:, 0] $\gets$ BOS \Comment{{  Set BOS as first token}}
    \State k $\gets$ L/K \Comment{{  Number of tokens to denoise at each step}}
    \State clean\_positions $\gets$ zeros(BS, 1) \Comment{{  Keep track of clean and noisy positions}}
    \State concrete\_lengths $\gets$ ones(BS, 1) \Comment{{  Keep track of the actual length of each sequence (some are padded).}}
    \State noisy\_positions $\gets$ $1 + $ rand\_row\_perm(BS, L-1)

    \For{\_ in range(K)}
        \State n\_denoise\_per\_seq, noisy\_pos\_input $\gets$ \textcolor{blue}{sample\_noisy}(noisy\_positions, k) \Comment{{  Algorithm \algo{algo:sample_noisy}}}
        \State new\_values $\gets$ pgm\_predict(x, clean\_positions, noisy\_pos\_input) 

        \State x, clean\_positions, noisy\_positions, concrete\_lengths $\gets$ \textcolor{blue}{extract\_predictions}( 
        \State \hspace{2em}x, \Comment{{  Algorithm \algo{algo:extract_predictions}}}
        \State \hspace{2em}clean\_positions, 
        \State \hspace{2em}noisy\_positions, 
        \State \hspace{2em}noisy\_pos\_input, 
        \State \hspace{2em}concrete\_lengths, 
        \State \hspace{2em}n\_denoise\_per\_seq, 
        \State \hspace{2em}new\_values) 
    \EndFor

    \State out $\gets$ reorder(x, clean\_positions) \Comment{{  Sort based on clean\_positions}}
    \State \Return out
    \end{algorithmic}

\end{algorithm}

\begin{algorithm}[t]
    \caption{Sample the number of tokens to denoise from a binomial distribution and pad the input.}
    \begin{algorithmic}[1]
    \State Input: Noisy positions tensor, probability of denoising prob\_denoise, model length L, concrete lengths tensor
    \State Output: Noisy positions to denoise

    \State n\_denoise\_per\_seq $\gets$ binomial(BS, L, prob\_denoise) \Comment{{  Sample from binomial distribution}}
    \State n\_denoise\_per\_seq $\gets$ min(n\_denoise\_per\_seq, L - concrete\_lengths) \Comment{{  Don't denoise more than available}}
    \State denoise\_seq\_len $\gets$ max(n\_denoise\_per\_seq, 0) \Comment{{  Maximum number of tokens to denoise}}

    \If{denoise\_seq\_len = 0}
        \State \Return empty\_tensor() \Comment{{  Nothing to denoise}}
    \EndIf

    \State noisy\_pos\_input $\gets$ noisy\_positions[:, :denoise\_seq\_len] \Comment{{  Some predictions won't be used}}
    \State \Return n\_denoise\_per\_seq, noisy\_pos\_input
    \end{algorithmic}

\end{algorithm}

\begin{algorithm}[t]
    \caption{Extract the correct number of predictions per sequence}
    \begin{algorithmic}[1]
    \State Input: x, concrete\_lengths, n\_denoise\_per\_seq, denoised\_token\_values, clean\_positions, noisy\_positions, noisy\_pos\_input
    \State Output: Updated x, clean\_positions, noisy\_positions, concrete\_lengths

    \State new\_concrete\_lengths $\gets$ concrete\_lengths + n\_denoise\_per\_seq \Comment{{ Update sequence lengths}}
    \State n\_tok\_to\_add $\gets$ max(new\_concrete\_lengths) - shape(x, 1) \Comment{{ Calculate padding needed}}

    \If{n\_tok\_to\_add > 0}
        \State pad $\gets$ zeros(BS, n\_tok\_to\_add) \Comment{{ Create padding tensor}}
        \State x $\gets$ concat(x, pad, dim=1) \Comment{{  Pad the sequences}}
        \State clean\_positions $\gets$ concat(clean\_positions, pad, dim=1) \Comment{{ Pad the positions}}
    \EndIf

    \For{i in range(BS)}
        \If{n\_denoise\_per\_seq[i] = 0}
            \State continue \Comment{{Skip if no tokens to denoise}}
        \EndIf

        \State x[i, concrete\_lengths[i]:new\_concrete\_lengths[i]] $\gets$ 
        \State \hspace{2em}denoised\_token\_values[i, :n\_denoise\_per\_seq[i]]
        \State clean\_positions[i, concrete\_lengths[i]:new\_concrete\_lengths[i]] $\gets$ 
        \State \hspace{2em}noisy\_pos\_input[i, :n\_denoise\_per\_seq[i]]
        \State noisy\_positions[i, :shape(noisy\_positions, 1) - n\_denoise\_per\_seq[i]] $\gets$ 
        \State \hspace{2em}noisy\_positions[i, n\_denoise\_per\_seq[i]:]
    \EndFor

    \State \Return x, clean\_positions, noisy\_positions, new\_concrete\_lengths
    \end{algorithmic}

\end{algorithm}

