			\theta_t - \theta_*\\
			\omega_t - \omega_*
		\end{bmatrix} - \eta \begin{bmatrix}
			\nabla_{\theta} U(\theta_t, \omega_t) \\
			-\nabla_{\omega} U(\theta_t, \omega_t)
		\end{bmatrix} \enspace,
		 \\
		&= \begin{bmatrix}
