			-\nabla_{\omega \theta} U( \theta(x), \omega(x)) & -\nabla_{\omega \omega} U( \theta(x), \omega(x)) 
		\end{bmatrix}    
			 d x \cdot \begin{bmatrix}
			 	\theta_t - \theta_* \\
				\omega_{t} - \omega_*
			 \end{bmatrix} \enspace, \\
		& =  \int_0^1 \left( I - \eta \begin{bmatrix}
			\nabla_{\theta\theta} U( \theta(x), \omega(x)) & \nabla_{\theta \omega} U( \theta(x), \omega(x)) \\
			-\nabla_{\omega \theta} U( \theta(x), \omega(x)) & -\nabla_{\omega \omega} U( \theta(x), \omega(x)) 
		\end{bmatrix}  \right) dx \cdot \begin{bmatrix}
			 	\theta_t - \theta_* \\
				\omega_{t} - \omega_*
			 \end{bmatrix} \enspace.
	\end{align*}
	Assume that one can prove for some $r >0$, and $(\theta, \omega) \in B_2((\theta_*, \omega_*), r)$, with a proper choice of $\eta$, the largest singular value is bounded above by 1,  
	\begin{align*}
		\left\| I - \eta \begin{bmatrix}
