	\begin{align*}
		\left\| \begin{bmatrix}
			\theta_{t+1} - \theta_*\\
			\omega_{t+1} - \omega_*
		\end{bmatrix} \right\| 
		&\leq 
		\left\|
		\int_0^1 \left( I - \eta 

