\subsubsection*{Step 2: Consistency of conditional cdf and pair-copula density estimators}

With arguments almost identical to those in Step 1, we can furthermore show that for all $e \in E_1, \dots, E_{d-1}$, and all $\bm x \in \Omega_{\bm X}$,
\begin{align} 
	\begin{aligned}
		 \wh F_{j_e|D_e}\bigl(x_{j_e} | {\bm x}_{D_e}\bigr) - F_{j_e|D_e}\bigl(x_{j_e} | \bm x_{D_e}\bigr) &= o_p(n^{-r}), \\
		\wh F_{k_e|D_e}\bigl(x_{k_e} |{\bm x}_{D_e}\bigr)- F_{k_e|D_e}\bigl(x_{k_e} | \bm x_{D_e}\bigr) &= o_p(n^{-r}).
	\end{aligned}
\end{align}
Next, we establish that for all $e \in E_1, \dots, E_{d-1}$, and all $(u, v) \in (0, 1)^2$,
\begin{align}  
 \wh c_{j_e,k_e;D_e}\bigl(u, v\bigr) -  c_{j_e,k_e;D_e}\bigl(u, v\bigr) = O_p(n^{-r}).
\end{align}
The triangle inequality gives
\begin{eqnarray*}
    & & \bigl\vert \wh c_{j_e,k_e;D_e}\bigl(u, v\bigr) -  c_{j_e,k_e;D_e}\bigl(u, v\bigr)\bigr\vert  \\
    &\le & \bigl\vert \wh c_{j_e,k_e;D_e}\bigl(u, v\bigr) - \overline c_{j_e,k_e;D_e}\bigl(u, v\bigr)\bigr\vert + \bigl\vert \overline c_{j_e,k_e;D_e}\bigl(u, v\bigr) -  c_{j_e,k_e;D_e}\bigl(u, v\bigr)\bigr\vert  \\
       &=& R_{n,1} + R_{n, 2}.
\end{eqnarray*}
We have $R_{n, 1} = o_{a.s.}(n^{-r})$ by \hyperref[Theory:bound_ass]{\ref*{Theory:bound_ass}a} and [REF:Theory:Uproof_eq], whereas $R_{n, 2} = O_p(n^{-r})$ by  \hyperref[Theory:oracle_ass]{\ref*{Theory:oracle_ass}a}.

\subsubsection*{Step 3: Consistency of the vine copula based density estimator}

The consistency of $\wh f_{\mathrm{vine}}$ now follows from [REF:Theory:cproof_eq] and \hyperref[Theory:f_ass]{\ref*{Theory:f_ass}a} (second equality) together with [REF:Theory:Fproof_eq] and the fact that $c_{j_e, k_e; D_e}$ is continuously differentiable (third equality):
\begin{align*} \allowdisplaybreaks[1]
	\wh f_{\mathrm{vine}}(\bm x) &= \prod_{k=1}^{d-1} \prod_{e \in E_k} \wh c_{j_e, k_e; D_e} \bigl\{\wh F_{j_e|D_e}(x_{j_e}|{\bm x}_{D_e}), \, \wh F_{k_e|D_e}(x_{k_e}|{\bm  x}_{D_e})\bigr\} \times \prod_{j=1}^d \wh f_j(x_j)\\ 
	&= \prod_{k=1}^{d-1} \prod_{e \in E_k}  \biggl[c_{j_e, k_e; D_e} \bigl\{\wh F_{j_e|D_e}(x_{j_e}|{\bm x}_{D_e}), \,  \wh F_{k_e|D_e}(x_{k_e}|{\bm  x}_{D_e})\bigr\} + O_p(n^{-r})\biggr] \\ 
& \phantom{=} \times \prod_{j=1}^d \bigl\{f_j(x_j) +O_p(r^{-r})\bigr\}\\
	&= \prod_{k=1}^{d-1} \prod_{e \in E_k}  \biggl[c_{j_e, k_e; D_e} \bigl\{ F_{j_e|D_e}(x_{j_e}|{\bm x}_{D_e}), \,  F_{k_e|D_e}(x_{k_e}|{\bm  x}_{D_e})\bigr\} + O_p(n^{-r}) + o_p(n^{-r})\biggr] \\ 
	& \phantom{=} \times \prod_{j=1}^d \bigl\{f_j(x_j) +O_p(n^{-r})\bigr\}\\\ 
	&=  f(\bm x)  +  O_p(n^{-r}). \tag*{\qed}
\end{align*}

