\subsection{Results}
\
\begin{Lemma} 
Under conditions [REF:K1], [REF:K2], [REF:C1],  and [REF:C2] it holds for all $(u,v) \in (0,1)^2$, 
	\begin{align*}
		\wh c(u,v) = \overline c(u, v) + O_{a.s}(a_n). 
        \end{align*}
\end{Lemma}
\begin{proof}
By a first-order Taylor approximation of $\Phi^{-1}$, $j =1, 2$,
\begin{align} 
\begin{aligned}  
	 \wh Z_j^{(i)} - Z_j^{(i)} &= (\wh W_j^{(i)} - W_j^{(i)})/ \phi(Z_j^{(i)}) + o_{a.s.}(\wh W_j^{(i)} - W_j^{(i)}) \\
     &= 1/\phi(Z_j^{(i)}) \times O_{a.s.}(a_n), 
     \end{aligned}
\end{align}
where the $O_{a.s.}(a_n)$ term does not depend on the index $i$ since the supremum was taken.
Denote $\nabla_{\bm z} = (\partial/\partial z_1, \partial/\partial z_2)^\top$. A first-order Taylor approximation of $K$ yields
	\begin{align*}
     &\phantom{=} \phi(z_1)\phi(z_2) \bigl\vert\wh c \bigl\{\Phi(z_1), \Phi(z_2) \bigr\}- \overline c\bigl\{\Phi(z_1), \Phi(z_2) \bigr\}\bigr\vert \\
  &=  \biggl\vert \frac{1}{n} \sum_{i= 1}^n K_{b_n}\bigl(z_1 - \wh Z_1^{(i)}\bigr) K_{b_n}\bigl(z_2 - \wh Z_2^{(i)}\bigr) -  \frac{1}{n} \sum_{i= 1}^n K_{b_n}\bigl(z_1 - Z_1^{(i)}\bigr) K_{b_n}\bigl(z_2 - Z_2^{(i)}\bigr)  \biggr\vert\\
  &=  \biggl\vert \frac{1}{n} \sum_{i= 1}^n \nabla_{\bm z} \bigl\{K_{b_n}(z_1 -Z_1^{(i)}) K_{b_n}(z_2 - Z_2^{(i)})\bigr\} \begin{pmatrix}
\wh Z_1^{(i)} - Z_1^{(i)} \\
\wh Z_2^{(i)} - Z_2^{(i)}
\end{pmatrix} + o_{a.s.}\biggl\{\begin{pmatrix}
\wh Z_1^{(i)} - Z_1^{(i)} \\
\wh Z_2^{(i)} - Z_2^{(i)}
\end{pmatrix}\biggr\}\biggr\vert \\
&\le  \biggl\vert \frac{1}{n} \sum_{i= 1}^n \nabla_{\bm z} \bigl\{K_{b_n}(z_1 - Z_1^{(i)}) K_{b_n}(z_2 - Z_2^{(i)})\bigr\} \begin{pmatrix}
1 / \phi\bigl(Z_1^{(i)}\bigr) \\
1 / \phi\bigl(Z_2^{(i)}\bigr)
\end{pmatrix} \biggr\vert \times O_{a.s.}(a_n),
	\end{align*}
    where the last inequality is due to [REF:Z_eq].  Since  $K_{b_n}$ is zero outside of $[-b_n, b_n]$, we can bound this further by
    \begin{align} 
 \eta_n(\bm z) \times \biggl\vert \nabla_{\bm z} \biggl\{\frac{1}{n} \sum_{i= 1}^n K_{b_n}(z_1 - Z_1^{(i)}) K_{b_n}(z_2 - Z_2^{(i)})\biggr\}  \biggr\vert \times O_{a.s.}(a_n),
\end{align}
where $\eta_n(\bm z) := \sup_{y \in [\min\{z_1,z_2\} - b_n, \max\{z_1, z_2\} + b_n]} 1 / \phi(y) = O(1)$ for all $\bm z \in \R^2$. The second term is the absolute value of the gradient of a classical kernel density estimator. Since the derivatives of $\psi$ are continuous and bounded by [REF:C2], it holds,
    \begin{align*}
  \biggl\vert \nabla_{\bm z} \biggl\{\frac{1}{n} \sum_{i= 1}^n K_{b_n}(z_1 - Z_1^{(i)}) K_{b_n}(z_2 - Z_2^{(i)})\biggr\}  \biggr\vert = \bigl\vert \nabla_{\bm z} \psi(z_1,z_2)\bigr\vert + o_{a.s.}(1),
\end{align*}
see Theorem 9 in [CITE:Hansen08]. Plugging this into [REF:displ] proves our claim. 

\end{proof}

\begin{Lemma} 
Under conditions [REF:K1], [REF:K2], [REF:C1], and [REF:C2]  it holds for all $(u,v) \in (0,1)^2$, $\delta \in (0, 0.5]$,  

	\begin{align*}
		\sup_{(u, v) \in [\delta, 1- \delta]^2} \bigl\vert \overline h(u|v) - h(u|v) \bigl\vert  =  O_{a.s.}\bigl(b_n^2 + \sqrt{\ln n / (nb_n)}\bigr).
	\end{align*}
\end{Lemma}	
 \begin{proof}
Equations 40 and 41 in [CITE:Hansen04] yield
\begin{align*}
	\E\bigl\{\overline h(u | v)\bigr\} - h\bigr(u | v \bigl) = b_n^2 \beta(u, v) + o(b_n^2),
\end{align*}
for some bias term $\beta(u, v)$ involving $h$ and $\phi$ as well as their first- and second order derivatives. Since all parts are continuous on $[\delta, 1- \delta]^2$ by [REF:C1] for all $\delta \in (0, 0.5]$, it holds
\begin{align*}
	\sup_{(u, v) \in [\delta, 1 - \delta]^2} \bigl\vert \E\bigl\{\overline h(u | v)\bigr\} - h\bigr(u | v)  \bigr\vert = O_{a.s.}\bigl(b_n^2\bigr).
\end{align*}
On the other hand, Lemma 2.2 of [CITE:Haerdle88] ensures that
\begin{align*}
	\sup_{(u, v) \in [\delta, 1 - \delta]^2} \bigl\vert \overline h(u | v) - \E\bigl\{\overline h(u | v)\bigr\} \bigr\vert = O_{a.s.}\bigl(\sqrt{\ln n / (nb_n)}\bigr).
\end{align*}
Combining the previous two equations concludes the proof.
\end{proof} 

 \begin{Lemma} 
Under conditions [REF:K1], [REF:K2], [REF:C1], and [REF:C2]  it holds for all $(u,v) \in (0,1)^2$, $\delta \in (0, 0.5]$,  
	\begin{align*}
		\sup_{(u, v) \in [\delta, 1- \delta]^2} \bigl\vert \wh h(u|v) - \overline h(u|v) \bigl\vert  =  O_{a.s.}\bigl(a_{n}\bigr).
	\end{align*}
\end{Lemma}
\begin{proof}
	With arguments similar to the proof of [REF:lem:c], we can show
    \begin{align*}
        		&\sup_{(u, v) \in [\delta, 1- \delta]^2} \bigl\vert \wh h(u|v) - \overline h(u|v) \bigl\vert \\
		&\sup_{\bm z \in [\Phi^{-1}(\delta), \Phi^{-1}(1- \delta)]^2} \bigl\vert \wh h\bigl\{\Phi(z_1)| \Phi(z_2) \bigr\} - \overline h\bigl\{\Phi(z_1)| \Phi(z_2) \bigr\} \bigr\vert \\
        \le &\sup_{\bm z \in [\Phi^{-1}(\delta), \Phi^{-1}(1- \delta)]^2} \biggl\vert \frac{\eta_n(\bm z)}{\phi(z_2)} \times  \nabla_{\bm z} h\bigl\{\Phi(z_1)| \Phi(z_2) \bigr\} \biggr\vert \times O_{a.s.}(a_n), 
	\end{align*}
    where $\eta_n(\bm z) = \sup_{y \in [\min\{z_1,z_2\} - b_n, \max\{z_1, z_2\} + b_n]} 1 / \phi(y)$ and the $O_{a.s}$ term is independent of $\bm z$.  The supremum on the right hand side is $O(1)$ because all functions are continuous in $\bm z$ on every compact subset of $\R^2$. As a result, the right can be bounded by a constant times the $O_{a.s.}(a_n)$ term. This establishes our claim.
\end{proof}

# proof_of_proposition_5

From [REF:prop:fhat]  and condition (v) in [REF:prop:an] we get for all $\ell = 1, \dots, d,$ and $x \in \R$, that  $\wh f_\ell(x)  = f_\ell(x) + o_p\{b_{n,c}^2 + (nb_{n,c}^2)^{-1/2}\}$. This implies $(nb_{n,c}^2)^{1/2}\bigl\{\wh f_\ell(x) - f_\ell(x)\bigr\} = o_p(1)$ and we have established that the first $d$ components of [REF:joint_an] converge to zero in probability. Hence, the first $d$ components of ${\bm \mu}_{\bm x}$ as well as the first $d$ rows and columns of $\Sigma_{\bm x}$ will be zero and we only have to deal with the remaining components in [REF:joint_an].

From [REF:Theory:cproof_eq] and [REF:Theory:Fproof_eq] in the proof of [REF:Theory:rate_thm] and [REF:prop:chat] we furthermore know that $\wh c_{j_e,k_e;D_e}(u,v) = \overline c_{j_e,k_e;D_e}(u,v) + o_p\{b_{n,c}^2 + (nb_{n,c}^2)^{-1/2}\}$ as well as $\wh F_{j_e|D_e}(x_{j_e}|\bm x_{D_e}) = F_{j_e|D_e}(x_{j_e}|\bm x_{D_e}) + o_p\{b_{n,c}^2 + (nb_{n,c}^2)^{-1/2}\}$. Similar to [REF:lem:h2], we can now show that
\begin{align*}
	&\overline c_{j_e,k_e;D_e}\bigl\{\wh F_{j_e|D_e}(x_{j_e}|\bm x_{D_e}), \wh F_{k_e|D_e}(x_{k_e}|\bm x_{D_e})\bigr\}\\
    =\;& \overline c_{j_e,k_e;D_e}\bigl\{F_{j_e|D_e}(x_{j_e}|\bm x_{D_e}), F_{k_e|D_e}(x_{k_e}|\bm x_{D_e})\bigr\} + o_p\{b_{n,c}^2 + (nb_{n,c}^2)^{-1/2}\}.
\end{align*}
Hence, for [REF:joint_an] to hold it suffices to show that 
    \begin{align} 
		(nb_{n, c}^2)^{1/2}\bigl\{\overline{\bm c}^*(\bm x) - b_{n,c}^2  \tilde{\bm\mu}_{\bm x} - {\bm c}^*(\bm x)\bigr\} \stackrel{d}{\to} \mathcal{N}\bigl(0, \tilde \Sigma_{\bm x}\bigr),
	\end{align}
     where

    $$\overline{\bm c}^*(\bm x) = \bigl(\overline c_{j_e,k_e;D_e}\{F_{j_e|D_e}(x_{j_e}|\bm x_{D_e}), F_{k_e|D_e}(x_{k_e}|\bm x_{D_e})\}\bigr)_{e \in E_1, \dots, E_{d-1}},$$ 
    and ${\bm c}^*(\bm x)$ is defined similarly, but replacing $\overline c_{j_e,k_e;D_e}$ with $c_{j_e,k_e;D_e}$. 

    Define $Z_{j_e|D_e}^{(i)} := \Phi^{-1}(U_{j_e|D_e}^{(i)} )$, $Z_{k_e|D_e}^{(i)} := \Phi^{-1}(U_{k_e|D_e}^{(i)})$,  $z_{j_e|D_e} := \Phi^{-1}\bigl\{F_{j_e|D_e}(x_{j_e}|\bm x_{D_e})\bigr\}$, $z_{k_e|D_e} := \Phi^{-1}\bigl\{F_{k_e|D_e}(x_{k_e}|\bm x_{D_e})\bigr\}$. Let $\bm Y_{n,i} := (Y_{n,i,e})_{e \in E_1, \dots, E_{d-1}}$, be a vector with entries
    \begin{align*}
		Y_{n,i,e} :=(nb_{n,c}^2)^{-1/2} \frac{K\biggl(\frac{Z_{j_e|D_e}^{(i)} - z_{j_e|D_e}}{b_n}\biggr) K\biggl(\frac{Z_{k_e|D_e}^{(i)} - z_{k_e|D_e}}{b_n}\biggr)}{ \phi(z_{j_e|D_e})\phi(z_{k_e|D_e})}.
	\end{align*}
    Then, $\sum_{i=1}^n \bm Y_{n,i} = (nb_{n,c}^2)^{1/2} \overline{\bm c}^*(\bm x)$.
    By the multivariate Lindeberg-Feller central limit theorem (Proposition 2.27 in [CITE:vanderVaart98]), [REF:joint_an_c] holds when  
    \begin{align}
	&\sum_{i=1}^n \E\bigl(\bm Y_{n, i}\bigr) = (nb_{n,c}^2)^{1/2}\bigl\{\bm c^*(\bm x) + b_{n,c}^2\tilde{\bm \mu}_{\bm x} + o(b_{n,c}^2)\bigr\},  \\
    &\sum_{i=1}^n \cov(\bm Y_{n,i}) \to \tilde \Sigma_{\bm x},  \\
    &\sum_{i=1}^n \E\bigl\{\| \bm Y_{n,i} \|^2 \ind\bigl(\| \bm Y_{n,i} \| > \varepsilon\bigr) \bigr\} \to 0, \quad \mbox{for all } \varepsilon > 0. 
	\end{align}
    Since $\bm Y_{n,i}$ are independent for $i = 1, \dots, n$, it holds 
   \begin{align*}
	\sum_{i=1}^n \E\bigl(\bm Y_{n, i}\bigr) = n \E\bigl(\bm Y_{n, i}\bigr), \qquad \sum_{i=1}^n \cov(\bm Y_{n,i}) = n \cov(\bm Y_{n,i}). 
\end{align*}
	Denote further $u_{j_e|D_e} := F_{j_e|D_e}(x_{j_e}|\bm x_{D_e})$,  $u_{k_e|D_e} := F_{k_e|D_e}(x_{k_e}|\bm x_{D_e})$. Corollary 3.4 in [CITE:Nagler14] gives
    \begin{align} 
	n\E\bigl(Y_{n,i,e}\bigr) = (nb_{n,c}^2)^{1/2} \bigl\{c_{j_e,k_e;D_e}(u_{j_e|D_e}, u_{k_e|D_e}) + b_{n,c}^2 \tilde{\mu}_{\bm x, e} + o(b_{n,c}^2)\bigr\},
\end{align}
where 
\begin{align} 
	\tilde{\mu}_{\bm x, e} &:= \biggl\{\frac{\partial^2c_{j_e,k_e;D_e}\bigl(u_{j_e|D_e},u_{k_e|D_e}\bigr)}{\partial u_{j_e|D_e}^2}  \phi^2(z_{j_e|D_e}) + \frac{\partial^2 c_{j_e,k_e;D_e}\bigl(u_{j_e|D_e}, u_{k_e|D_e}\bigr)}{\partial u_{k_e|D_e}^2}  \phi^2(z_{k_e|D_e}) \notag \\
       \begin{split}
	&\phantom{:=\biggl[}- \frac{3 \partial c_{j_e,k_e;D_e}\bigl(u_{j_e|D_e},u_{k_e|D_e}\bigr)}{\partial u_{j_e|D_e}}  \phi(z_{j_e|D_e})z_{j_e|D_e} \\ 
    &\phantom{:=\biggl[} - \frac{3 \partial c_{j_e,k_e;D_e}\bigl(u_{j_e|D_e},u_{k_e|D_e}\bigr)}{\partial u_{k_e|D_e}} \phi(z_{k_e|D_e})z_{k_e|D_e} 
    \end{split}  \\
	&\phantom{:=\biggl[}  + c_{j_e,k_e;D_e}\bigl(u_{j_e|D_e}, u_{k_e|D_e}\bigr) \times  \bigl(z_{j_e|D_e}^2 + z_{k_e|D_e}^2-2\bigr)  \biggr\} \frac {\sigma_K^2}{2}, \notag 
\end{align}
and $\sigma_K^2 := \int_{[-1, 1]}x^2K(x)dx$. This validates  [REF:LF1]. By the change of variable $s_1 = (z_1 - z_{j_e|D_e})/b_{n,c}$, $s_2 = (z_2 - z_{k_e|D_e})/b_{n,c}$, and a Taylor approximation of $\psi_{j_e, k_e;D_e}$ (as defined in [REF:C2]), we get
\begin{align}
&  n\E\bigl(Y_{n,i,e}^2\bigr) \phi^2(z_{j_e|D_e})\phi^2(z_{k_e|D_e}) \notag \\
=\; & n\E\biggl\{\frac{1}{nb_{n,c}^2} K^2\biggl(\frac{Z_{j_e|D_e}^{(i)} - z_{j_e|D_e}}{b_{n,c}}\biggr) K^2\biggl(\frac{Z_{k_e|D_e}^{(i)} - z_{k_e|D_e}}{b_{n,c}}\biggr)  \biggr\} \notag  \\
    =\; & \int_\R \int_\R K^2(s_1)K^2(s_2)\psi_{j_e, k_e;D_e}(z_{j_e|D_e} - b_{n,c} s_1, z_{k_e|D_e} - b_{n,c} s_2) ds_1 ds_2 \notag \\
    = \;& \nu_K^2 \psi_{j_e, k_e;D_e}(z_{j_e|D_e}, z_{k_e|D_e}) + o(1), 
\end{align}
where $\nu_{K} := \int_\R K^2(s)ds$. Using [REF:var_calc] and [REF:bias_calc], we obtain
\begin{align} 
	n\var(Y_{n, i, e})  
    \to \nu_K^2 \frac{c_{j_e,k_e;D_e}\bigl(u_{j_e|D_e},u_{k_e|D_e}\bigr)}{\phi(z_{j_e|D_e})\phi(z_{k_e|D_e})} =: \tilde \sigma_{\bm x, e}.
